  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { useCoreKitAuth } from '../lib/web3auth/hooks';
  4→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
  5→import { authApi } from '../lib/api/auth';
  6→import { vaultApi } from '../lib/api/vault';
  7→import { useAuthStore } from '../stores/auth.store';
  8→import { useFolderStore } from '../stores/folder.store';
  9→import { useVaultStore } from '../stores/vault.store';
 10→import { useDeviceRegistryStore } from '../stores/device-registry.store';
 11→import { clearAllUserStores } from '../lib/clear-user-stores';
 12→import { initSdkClient } from '../lib/sdk-provider';
 13→// api-config.ts handles setApiClientConfig at module load time
 14→import {
 15→  initializeVault,
 16→  encryptVaultKeys,
 17→  decryptVaultKeys,
 18→  detectBlobVersion,
 19→  deserializeVaultBlobV2,
 20→  serializeVaultBlobV2,
 21→} from '@cipherbox/core';
 22→import {
 23→  deriveIpnsName,
 24→  deriveVaultIpnsKeypair,
 25→  hexToBytes,
 26→  bytesToHex,
 27→  wrapKey,
 28→  unwrapKey,
 29→} from '@cipherbox/crypto';
 30→import { getOrCreateDeviceIdentity } from '../lib/device/identity';
 31→import { detectDeviceInfo } from '../lib/device/info';
 32→import { initializeOrSyncRegistry } from '../services/device-registry.service';
 33→import { initializeBin } from '../services/bin.service';
 34→import { useBinStore } from '../stores/bin.store';
 35→import { vaultControllerGetConfig, vaultControllerMigrateVault } from '@cipherbox/api-client';
 36→import { createAndPublishIpnsRecord, resolveIpnsRecord } from '../services/ipns.service';
 37→import { addToIpfs, fetchFromIpfs } from '../lib/api/ipfs';
 38→
 39→export function useAuth() {
 40→  const navigate = useNavigate();
 41→  const {
 42→    isLoggedIn: coreKitLoggedIn,
 43→    isInitialized: coreKitInitialized,
 44→    isRequiredShare,
 45→    loginWithGoogle: coreKitLoginGoogle,
 46→    loginWithEmailOtp: coreKitLoginEmail,
 47→    loginWithWallet: coreKitLoginWallet,
 48→    getVaultKeypair,
 49→    getPublicKeyHex,
 50→    logout: coreKitLogout,
 51→  } = useCoreKitAuth();
 52→  const { syncStatus } = useCoreKit();
 53→  const {
 54→    accessToken,
 55→    isAuthenticated,
 56→    lastAuthMethod,
 57→    userEmail,
 58→    setAccessToken,
 59→    setAuthenticated,
 60→    setLastAuthMethod,
 61→    setUserEmail,
 62→    setVaultKeypair,
 63→  } = useAuthStore();
 64→
 65→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 66→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 67→  const restoringRef = useRef(false);
 68→
 69→  // Stable refs for functions used in the session restoration effect.
 70→  // This prevents the effect from re-firing when function references change.
 71→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 72→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 73→
 74→  // Pending auth state for REQUIRED_SHARE flow.
 75→  // Stored in Zustand (not useState) so the state is shared across all
 76→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 77→  // via its own useAuth() call.
 78→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 79→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 80→
 81→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 82→
 83→  // Get vault store actions
 84→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 85→
 86→  /**
 87→   * Initialize vault for new users or load existing vault keys.
 88→   * Called after successful backend authentication.
 89→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 90→   */
 91→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 92→    // Get user's secp256k1 keypair from Core Kit TSS export
 93→    const userKeypair = await getVaultKeypair();
 94→
 95→    if (!userKeypair) {
 96→      throw new Error('Failed to get vault keypair from Core Kit');
 97→    }
 98→
 99→    // Store keypair in auth store for crypto operations
100→    setVaultKeypair(userKeypair);
101→
102→    try {
103→      // Try to fetch existing vault
104→      const existingVault = await vaultApi.getVault();
105→
106→      // Store TEE keys if available
107→      if (existingVault.teeKeys) {
108→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
109→      }
110→
111→      if (existingVault.migratedAt) {
112→        // PATH A: Migrated user -- read rootFolderKey from IPFS v2 blob
113→        // Derive IPNS keypair once (used for both resolution and vault keys)
114→        const ipnsKeypair = await deriveVaultIpnsKeypair(userKeypair.privateKey);
115→        let rootFolderKey: Uint8Array;
116→        try {
117→          const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);
118→
119→          // Resolve IPNS to CID using the existing IPNS service (handles signature verification)
120→          const resolved = await resolveIpnsRecord(ipnsName);
121→          if (!resolved) throw new Error('IPNS name not found for migrated vault');
122→
123→          // Fetch blob bytes from IPFS using the existing IPFS adapter
124→          const blobBytes = await fetchFromIpfs(resolved.cid);
125→
126→          if (detectBlobVersion(blobBytes) === 2) {
127→            const { encryptedRootFolderKey: encKey } = deserializeVaultBlobV2(blobBytes);
128→            rootFolderKey = await unwrapKey(encKey, userKeypair.privateKey);
129→          } else {
130→            throw new Error('Migrated vault but IPNS blob is v1 format');
131→          }
132→        } catch (ipfsError) {
133→          // Silent DB fallback for migrated users (per CONTEXT decision)
134→          console.warn('[Auth] v2 blob read failed, falling back to DB:', ipfsError);
135→          if (existingVault.encryptedRootFolderKey) {
136→            rootFolderKey = await unwrapKey(
137→              hexToBytes(existingVault.encryptedRootFolderKey as unknown as string),
138→              userKeypair.privateKey
139→            );
140→          } else {
141→            // DB fields are null and IPFS failed -- cannot recover
142→            throw new Error('Migrated vault: IPFS read failed and no DB fallback available');
143→          }
144→        }
145→
146→        setVaultKeys({
147→          rootFolderKey,
148→          rootIpnsKeypair: ipnsKeypair,
149→          rootIpnsName: existingVault.rootIpnsName,
150→          vaultId: existingVault.id,
151→        });
152→      } else {
153→        // PATH B: Non-migrated existing user -- decrypt from DB + trigger migration
154→        const decryptedVault = await decryptVaultKeys(
155→          {
156→            encryptedRootFolderKey: hexToBytes(
157→              existingVault.encryptedRootFolderKey as unknown as string
158→            ),
159→            encryptedIpnsPrivateKey: hexToBytes(
160→              existingVault.encryptedRootIpnsPrivateKey as unknown as string
161→            ),
162→          },
163→          userKeypair.privateKey
164→        );
165→
166→        setVaultKeys({
167→          rootFolderKey: decryptedVault.rootFolderKey,
168→          rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
169→          rootIpnsName: existingVault.rootIpnsName,
170→          vaultId: existingVault.id,
171→        });
172→
173→        // Non-blocking migration trigger: write v2 blob + call /vault/migrate
174→        void (async () => {
175→          try {
176→            // 1. ECIES-wrap rootFolderKey with user's publicKey
177→            const encryptedKey = await wrapKey(decryptedVault.rootFolderKey, userKeypair.publicKey);
178→
179→            // 2. Resolve current IPNS to get existing blob and sequence number
180→            const ipnsName = existingVault.rootIpnsName;
181→            const resolved = await resolveIpnsRecord(ipnsName);
182→            if (!resolved) throw new Error('IPNS name not found during migration');
183→            const currentSeqNo = resolved.sequenceNumber;
184→
185→            // 3. Fetch current blob (v1 JSON metadata)
186→            const existingMetadataJson = await fetchFromIpfs(resolved.cid);
187→
188→            // 4. Serialize as v2 blob
189→            const v2Blob = serializeVaultBlobV2(encryptedKey, existingMetadataJson);
190→
191→            // 5. Upload v2 blob to IPFS
192→            const uploadResult = await addToIpfs(new Blob([v2Blob as BlobPart]));
193→
194→            // 6. Derive HKDF keypair and publish IPNS record with seq+1
195→            const ipnsKeypair = await deriveVaultIpnsKeypair(userKeypair.privateKey);
196→            const publishResult = await createAndPublishIpnsRecord({
197→              ipnsPrivateKey: ipnsKeypair.privateKey,
198→              ipnsName,
199→              metadataCid: uploadResult.cid,
200→              sequenceNumber: currentSeqNo + 1n,
201→              expectedSequenceNumber: currentSeqNo.toString(),
202→            });
203→
204→            if (!publishResult.success) {
205→              throw new Error('IPNS publish failed during vault migration');
206→            }
207→
208→            // 7. Stamp migratedAt and NULL DB columns (only after confirmed write)
209→            await vaultControllerMigrateVault();
210→            console.log('[Auth] Vault successfully migrated to v2 blob format');
211→          } catch (migrationError) {
212→            // Migration failure is non-blocking. User can still use the app.
213→            // Migration will be retried on next login.
214→            console.warn(
215→              '[Auth] Vault v2 migration failed (will retry on next login):',
216→              migrationError
217→            );
218→          }
219→        })();
220→      }
221→    } catch (error) {
222→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
223→
224→      if (is404) {
225→        // New user - initialize vault
226→        console.log(
227→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
228→        );
229→        const newVault = await initializeVault(userKeypair.privateKey);
230→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
231→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
232→
233→        const storedVault = await vaultApi.initVault({
234→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
235→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
236→          // encryptedRootIpnsPrivateKey omitted -- HKDF derivation is canonical (VAULT-04)
237→          rootIpnsName,
238→        });
239→
240→        if (storedVault.teeKeys) {
241→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
242→        }
243→
244→        setVaultKeys({
245→          rootFolderKey: newVault.rootFolderKey,
246→          rootIpnsKeypair: newVault.rootIpnsKeypair,
247→          rootIpnsName,
248→          vaultId: storedVault.id,
249→          isNewVault: true,
250→        });
251→      } else {
252→        console.error('[useAuth] Failed to load vault:', error);
253→        throw error;
254→      }
255→    }
256→
257→    // Initialize SDK client with decrypted vault keys
258→    const vaultState = useVaultStore.getState();
259→    const authState = useAuthStore.getState();
260→    if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
261→      const apiUrl = import.meta.env.VITE_API_URL || window.location.origin + '/api';
262→      const getAccessToken = async () => {
263→        const state = useAuthStore.getState();
264→        return state.accessToken || '';
265→      };
266→
267→      // @cipherbox/api-client is configured in lib/api-config.ts at module load time.
268→
269→      const sdkClient = initSdkClient({
270→        apiUrl,
271→        getAccessToken,
272→        vaultKeypair: {
273→          publicKey: userKeypair.publicKey,
274→          privateKey: userKeypair.privateKey,
275→        },
276→        rootIpnsName: vaultState.rootIpnsName,
277→        rootFolderKey: vaultState.rootFolderKey,
278→        teeKeys: authState.teeKeys ?? undefined,
279→        shareCallbacks: {
280→          getCoveringShares: async (folderIpnsName: string) => {
281→            const { findCoveringShares } = await import('../services/share.service');
282→            const folders = useFolderStore.getState().folders;
283→            // Find the folder ID from IPNS name for ancestor traversal
284→            const folderId =
285→              Object.keys(folders).find((id) => folders[id].ipnsName === folderIpnsName) ?? null;
286→            return findCoveringShares(folderIpnsName, folders, folderId);
287→          },
288→          addShareKeys: async (shareId, keys) => {
289→            const { addShareKeys } = await import('../services/share.service');
290→            await addShareKeys(shareId, keys);
291→          },
292→        },
293→      });
294→
295→      // Subscribe folder store to SDK events
296→      useFolderStore.getState().subscribeToSdk(sdkClient);
297→
298→      // Subscribe bin store to SDK events
299→      useBinStore.getState().subscribeToSdk(sdkClient);
300→    }
301→
302→    // Non-blocking device registry initialization (fire-and-forget)
303→    // Placed after vault load so registry failures never block login
304→    void (async () => {
305→      try {
306→        const deviceKeypair = await getOrCreateDeviceIdentity({
307→          mode: 'persisted',
308→          vaultPrivateKey: userKeypair.privateKey,
309→        });
310→        const deviceInfo = detectDeviceInfo();
311→        const result = await initializeOrSyncRegistry({
312→          userPrivateKey: userKeypair.privateKey,
313→          userPublicKey: userKeypair.publicKey,
314→          deviceKeypair,
315→          deviceInfo: { ...deviceInfo, ipHash: '' },
316→        });
317→        if (result) {
318→          useDeviceRegistryStore
319→            .getState()
320→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
321→        }
322→      } catch (error) {
323→        console.error('[Auth] Device registry init failed (non-blocking):', error);
324→      }
325→    })();
326→
327→    // Non-blocking bin initialization (fire-and-forget)
328→    // After old service creates/loads bin, also load into SDK for deleteToBin support
329→    void (async () => {
330→      try {
331→        await initializeBin({
332→          userPrivateKey: userKeypair.privateKey,
333→          userPublicKey: userKeypair.publicKey,
334→        });
335→        // Now load bin into SDK (old service ensures bin IPNS record exists)
336→        const { getSdkClient, hasSdkClient } = await import('../lib/sdk-provider');
337→        if (hasSdkClient()) {
338→          await getSdkClient().loadBin();
339→        }
340→      } catch (error) {
341→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
342→      }
343→    })();
344→
345→    // Non-blocking: fetch retention config from API
346→    void (async () => {
347→      try {
348→        const config = await vaultControllerGetConfig();
349→        if (config.recycleBinRetentionDays != null) {
350→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
351→        }
352→      } catch (error) {
353→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
354→      }
355→    })();
356→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
357→
358→  /**
359→   * Complete backend authentication after Core Kit login.
360→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
361→   * to the backend with loginType 'corekit'. The backend verifies it against
362→   * its own JWKS since CipherBox is the identity provider.
363→   */
364→  const completeBackendAuth = useCallback(
365→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
366→      // 1. Get real publicKey from Core Kit TSS export
367→      const publicKey = await getPublicKeyHex();
368→      if (!publicKey) {
369→        throw new Error('Failed to get publicKey from Core Kit');
370→      }
371→
372→      // publicKey available for debugging via DevTools if needed
373→
374→      // 2. Authenticate with CipherBox backend
375→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
376→      const response = await authApi.login({
377→        idToken: cipherboxJwt,
378→        publicKey,
379→        loginType: 'corekit',
380→      });
381→
382→      // 3. Store access token (refresh token in HTTP-only cookie)
383→      // Note: this does NOT set isAuthenticated — we wait until vault + SDK
384→      // are fully initialized to prevent Login.tsx from redirecting to /files
385→      // before the SDK client is ready for file operations.
386→      setAccessToken(response.accessToken);
387→
388→      // 4. Remember auth method for UX
389→      setLastAuthMethod(authMethod);
390→
391→      // 5. Initialize or load vault + SDK client
392→      await initializeOrLoadVault();
393→
394→      // 6. Now that vault keys are loaded and SDK is initialized,
395→      // mark the user as authenticated. This triggers Login.tsx → /files redirect.
396→      setAuthenticated();
397→    },
398→    [getPublicKeyHex, setAccessToken, setAuthenticated, setLastAuthMethod, initializeOrLoadVault]
399→  );
400→
401→  /**
402→   * Complete the login flow after REQUIRED_SHARE is resolved.
403→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
404→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
405→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
406→   */
407→  const completeRequiredShare = useCallback(async (): Promise<void> => {
408→    // Read directly from Zustand store to get fresh values — this callback
409→    // may be called from useDeviceApproval's useAuth() instance, so we
410→    // can't rely on closure-captured selector values.
411→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
412→
413→    if (!jwt || !method) {
414→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
415→    }
416→
417→    // Core Kit should now be LOGGED_IN after inputFactorKey()
418→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
419→    await completeBackendAuth(method, jwt);
420→
421→    // NOW sync Core Kit React state to LOGGED_IN.
422→    // We deliberately delayed this from inputFactorKey() to prevent the session
423→    // restoration effect from firing before backend auth completed.
424→    // At this point isAuthenticated is true (from completeBackendAuth -> setAuthenticated),
425→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
426→    syncStatus();
427→
428→    // Clear pending state
429→    setPendingAuth(null, null);
430→
431→    // Navigate to files
432→    navigate('/files');
433→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
434→
435→  /**
436→   * Login with Google OAuth token.
437→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
438→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
439→   */
440→  const loginWithGoogle = useCallback(
441→    async (googleIdToken: string): Promise<void> => {
442→      if (isLoggingIn) return;
443→      setIsLoggingIn(true);
444→      try {
445→        // 1. Core Kit login via CipherBox identity provider
446→        const {
447→          cipherboxJwt,
448→          email,
449→          userId,
450→          status: coreKitStatus,
451→        } = await coreKitLoginGoogle(googleIdToken);
452→
453→        if (coreKitStatus === 'required_share') {
454→          // MFA enabled but device factor missing.
455→          // Store pending auth info for later completion after factor input.
456→          setPendingAuth(cipherboxJwt, 'google');
457→
458→          // Obtain temporary backend access token so the new device can
459→          // call bulletin board API endpoints (device-approval/*).
460→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
461→          // state and we can't export the TSS key yet.
462→          const tempLoginResponse = await authApi.login({
463→            idToken: cipherboxJwt,
464→            publicKey: `pending-core-kit-${userId}`,
465→            loginType: 'corekit',
466→          });
467→          setAccessToken(tempLoginResponse.accessToken);
468→
469→          if (email) {
470→            setUserEmail(email);
471→          }
472→
473→          // Do NOT call completeBackendAuth() or navigate('/files')
474→          // The component tree will see isRequiredShare === true and
475→          // render recovery/approval UI.
476→          return;
477→        }
478→
479→        // Normal path: Core Kit logged in, proceed as before
480→        // 2. Complete backend auth + vault init
481→        await completeBackendAuth('google', cipherboxJwt);
482→
483→        // 3. Store email for UI display (returned from identity endpoint)
484→        if (email) {
485→          setUserEmail(email);
486→        }
487→
488→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
489→      } catch (error) {
490→        console.error('[useAuth] Google login failed:', error);
491→        throw error;
492→      } finally {
493→        setIsLoggingIn(false);
494→      }
495→    },
496→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
497→  );
498→
499→  /**
500→   * Login with Email OTP.
501→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
502→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
503→   */
504→  const loginWithEmail = useCallback(
505→    async (email: string, otp: string): Promise<void> => {
506→      if (isLoggingIn) return;
507→      setIsLoggingIn(true);
508→      try {
509→        // 1. Core Kit login via CipherBox identity provider
510→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
511→
512→        if (coreKitStatus === 'required_share') {
513→          setPendingAuth(cipherboxJwt, 'email');
514→
515→          const tempLoginResponse = await authApi.login({
516→            idToken: cipherboxJwt,
517→            publicKey: `pending-core-kit-${userId}`,
518→            loginType: 'corekit',
519→          });
520→          setAccessToken(tempLoginResponse.accessToken);
521→          setUserEmail(email);
522→          return;
523→        }
524→
525→        // Normal path
526→        await completeBackendAuth('email', cipherboxJwt);
527→        setUserEmail(email);
528→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
529→      } catch (error) {
530→        console.error('[useAuth] Email login failed:', error);
531→        throw error;
532→      } finally {
533→        setIsLoggingIn(false);
534→      }
535→    },
536→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
537→  );
538→
539→  /**
540→   * Login with Wallet (SIWE).
541→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
542→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
543→   */
544→  const loginWithWallet = useCallback(
545→    async (cipherboxJwt: string, userId: string): Promise<void> => {
546→      if (isLoggingIn) return;
547→      setIsLoggingIn(true);
548→      try {
549→        // 1. Core Kit login via CipherBox identity provider
550→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
551→
552→        if (coreKitStatus === 'required_share') {
553→          setPendingAuth(cipherboxJwt, 'wallet');
554→
555→          const tempLoginResponse = await authApi.login({
556→            idToken: cipherboxJwt,
557→            publicKey: `pending-core-kit-${userId}`,
558→            loginType: 'corekit',
559→          });
560→          setAccessToken(tempLoginResponse.accessToken);
561→          return;
562→        }
563→
564→        // Normal path
565→        await completeBackendAuth('wallet', cipherboxJwt);
566→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
567→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
568→        // inside it may still be pending. An explicit navigate here would fire AFTER
569→        // vault init completes — by which point the user may have navigated away from
570→        // the login page, causing a disruptive late redirect.
571→      } catch (error) {
572→        console.error('[useAuth] Wallet login failed:', error);
573→        throw error;
574→      } finally {
575→        setIsLoggingIn(false);
576→      }
577→    },
578→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
579→  );
580→
581→  // Complete logout: Backend -> Core Kit -> Clear state
582→  const logout = useCallback(async () => {
583→    if (isLoggingOut) return;
584→
585→    setIsLoggingOut(true);
586→    try {
587→      // 1. Call backend logout (clears cookie)
588→      if (accessToken) {
589→        try {
590→          await authApi.logout();
591→        } catch {
592→          // Ignore errors -- we'll clear state anyway
593→        }
594→      }
595→
596→      // 2. Logout Core Kit (clears session from localStorage)
597→      await coreKitLogout();
598→
599→      // 3. Clear all user-scoped stores (centralized helper)
600→      clearAllUserStores();
601→
602→      // 4. Navigate to login
603→      navigate('/');
604→    } catch (error) {
605→      console.error('[useAuth] Logout failed:', error);
606→      // Still clear state even if backend fails
607→      clearAllUserStores();
608→      navigate('/');
609→    } finally {
610→      setIsLoggingOut(false);
611→    }
612→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
613→
614→  // Keep function refs up-to-date for use in session restoration effect.
615→  // Using refs prevents the effect from re-firing when function identities change.
616→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
617→  coreKitLogoutRef.current = coreKitLogout;
618→
619→  // Session restoration: if Core Kit restores a session from localStorage
620→  // on init, we have LOGGED_IN status without going through login flow.
621→  // Complete backend auth + vault loading.
622→  useEffect(() => {
623→    const restoreSession = async () => {
624→      // Only restore if Core Kit has a session but we don't have
625→      // a backend access token yet
626→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
627→        restoringRef.current = true;
628→        setIsLoggingIn(true);
629→        try {
630→          // Try to refresh using the HTTP-only cookie first
631→          const response = await authApi.refresh();
632→          setAccessToken(response.accessToken);
633→
634→          // Restore email from backend if available
635→          if (response.email) {
636→            setUserEmail(response.email);
637→          }
638→
639→          // Load vault keys from Core Kit keypair + initialize SDK
640→          await initializeOrLoadVaultRef.current?.();
641→
642→          // Mark as authenticated only after vault + SDK are ready
643→          setAuthenticated();
644→        } catch {
645→          // No valid backend session -- user needs to re-login
646→          // Core Kit session exists but backend cookie expired
647→          // Clear Core Kit session to avoid inconsistent state
648→          try {
649→            await coreKitLogoutRef.current?.();
650→          } catch {
651→            // Ignore logout errors during cleanup
652→          }
653→        } finally {
654→          restoringRef.current = false;
655→          setIsLoggingIn(false);
656→        }
657→      }
658→    };
659→    restoreSession();
660→  }, [
661→    coreKitLoggedIn,
662→    isAuthenticated,
663→    isLoggingIn,
664→    setAccessToken,
665→    setAuthenticated,
666→    setUserEmail,
667→  ]);
668→
669→  return {
670→    isLoading,
671→    isAuthenticated,
672→    isRequiredShare,
673→    lastAuthMethod,
674→    userEmail,
675→    pendingAuthMethod,
676→    loginWithGoogle,
677→    loginWithEmail,
678→    loginWithWallet,
679→    completeRequiredShare,
680→    logout,
681→  };
682→}
