  1→import { Injectable, ConflictException, NotFoundException } from '@nestjs/common';
  2→import { InjectRepository } from '@nestjs/typeorm';
  3→import { ConfigService } from '@nestjs/config';
  4→import { Repository } from 'typeorm';
  5→import { Vault } from './entities/vault.entity';
  6→import { PinnedCid } from './entities/pinned-cid.entity';
  7→import { FolderIpns } from '../ipns/entities/folder-ipns.entity';
  8→import { User } from '../auth/entities/user.entity';
  9→import { InitVaultDto, VaultResponseDto } from './dto/init-vault.dto';
 10→import { VaultExportDto } from './dto/vault-export.dto';
 11→import { QuotaResponseDto } from './dto/quota.dto';
 12→import { VaultConfigResponseDto } from './dto/vault-config.dto';
 13→import { TeeKeyStateService } from '../tee/tee-key-state.service';
 14→import { TeeKeysDto } from '../tee/dto/tee-keys.dto';
 15→
 16→/**
 17→ * Storage quota limit: 500 MiB
 18→ */
 19→export const QUOTA_LIMIT_BYTES = 500 * 1024 * 1024; // 524,288,000 bytes
 20→
 21→@Injectable()
 22→export class VaultService {
 23→  constructor(
 24→    @InjectRepository(Vault)
 25→    private readonly vaultRepository: Repository<Vault>,
 26→    @InjectRepository(PinnedCid)
 27→    private readonly pinnedCidRepository: Repository<PinnedCid>,
 28→    @InjectRepository(FolderIpns)
 29→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 30→    @InjectRepository(User)
 31→    private readonly userRepository: Repository<User>,
 32→    private readonly teeKeyStateService: TeeKeyStateService,
 33→    private readonly configService: ConfigService
 34→  ) {}
 35→
 36→  /**
 37→   * Get application configuration including recycle bin retention period.
 38→   */
 39→  getConfig(): VaultConfigResponseDto {
 40→    const raw = this.configService.get<string>('RECYCLE_BIN_RETENTION_DAYS');
 41→    let retentionDays = Number(raw);
 42→    if (!Number.isFinite(retentionDays) || retentionDays < 0) {
 43→      retentionDays = 30;
 44→    }
 45→    return {
 46→      recycleBinRetentionDays: retentionDays,
 47→    };
 48→  }
 49→
 50→  /**
 51→   * Initialize a new vault for a user
 52→   * Creates the vault with encrypted keys on first sign-in
 53→   *
 54→   * @throws ConflictException if vault already exists for user
 55→   */
 56→  async initializeVault(userId: string, dto: InitVaultDto): Promise<VaultResponseDto> {
 57→    // Check if vault already exists
 58→    const existingVault = await this.vaultRepository.findOne({
 59→      where: { ownerId: userId },
 60→    });
 61→
 62→    if (existingVault) {
 63→      throw new ConflictException('Vault already exists for this user');
 64→    }
 65→
 66→    // Decode hex strings to buffers
 67→    const vault = this.vaultRepository.create({
 68→      ownerId: userId,
 69→      ownerPublicKey: Buffer.from(dto.ownerPublicKey, 'hex'),
 70→      encryptedRootFolderKey: Buffer.from(dto.encryptedRootFolderKey, 'hex'),
 71→      encryptedRootIpnsPrivateKey: dto.encryptedRootIpnsPrivateKey
 72→        ? Buffer.from(dto.encryptedRootIpnsPrivateKey, 'hex')
 73→        : null,
 74→      rootIpnsName: dto.rootIpnsName,
 75→      initializedAt: null,
 76→    });
 77→
 78→    const savedVault = await this.vaultRepository.save(vault);
 79→
 80→    // Create root folder IPNS entry for publish tracking
 81→    // This allows IPNS publishes to work without requiring TEE fields on every publish
 82→    const rootFolderIpns = this.folderIpnsRepository.create({
 83→      userId,
 84→      ipnsName: dto.rootIpnsName,
 85→      latestCid: null, // No content yet
 86→      sequenceNumber: '0',
 87→      encryptedIpnsPrivateKey: null, // TEE key added when TEE is implemented
 88→      keyEpoch: null,
 89→      isRoot: true,
 90→    });
 91→    await this.folderIpnsRepository.save(rootFolderIpns);
 92→
 93→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
 94→    return this.toVaultResponse(savedVault, teeKeys);
 95→  }
 96→
 97→  /**
 98→   * Get vault for a user
 99→   *
100→   * @throws NotFoundException if vault does not exist
101→   */
102→  async getVault(userId: string): Promise<VaultResponseDto> {
103→    const vault = await this.vaultRepository.findOne({
104→      where: { ownerId: userId },
105→    });
106→
107→    if (!vault) {
108→      throw new NotFoundException('Vault not found');
109→    }
110→
111→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
112→    return this.toVaultResponse(vault, teeKeys);
113→  }
114→
115→  /**
116→   * Check if vault exists for user (returns null if not)
117→   */
118→  async findVault(userId: string): Promise<VaultResponseDto | null> {
119→    const vault = await this.vaultRepository.findOne({
120→      where: { ownerId: userId },
121→    });
122→
123→    if (!vault) return null;
124→
125→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
126→    return this.toVaultResponse(vault, teeKeys);
127→  }
128→
129→  /**
130→   * Get current storage quota usage for a user
131→   */
132→  async getQuota(userId: string): Promise<QuotaResponseDto> {
133→    const result = await this.pinnedCidRepository
134→      .createQueryBuilder('pin')
135→      .select('COALESCE(SUM(pin.size_bytes), 0)', 'total')
136→      .where('pin.user_id = :userId', { userId })
137→      .getRawOne<{ total: string }>();
138→
139→    const usedBytes = parseInt(result?.total ?? '0', 10);
140→    const remainingBytes = Math.max(0, QUOTA_LIMIT_BYTES - usedBytes);
141→
142→    return {
143→      usedBytes,
144→      limitBytes: QUOTA_LIMIT_BYTES,
145→      remainingBytes,
146→    };
147→  }
148→
149→  /**
150→   * Check if user has sufficient quota for additional storage
151→   *
152→   * @returns true if (current usage + additionalBytes) <= quota limit
153→   */
154→  async checkQuota(userId: string, additionalBytes: number): Promise<boolean> {
155→    const quota = await this.getQuota(userId);
156→    return quota.usedBytes + additionalBytes <= QUOTA_LIMIT_BYTES;
157→  }
158→
159→  /**
160→   * Record a pinned CID for quota tracking
161→   * Uses upsert (ON CONFLICT DO NOTHING) for idempotency
162→   */
163→  async recordPin(userId: string, cid: string, sizeBytes: number): Promise<void> {
164→    await this.pinnedCidRepository
165→      .createQueryBuilder()
166→      .insert()
167→      .into(PinnedCid)
168→      .values({
169→        userId,
170→        cid,
171→        sizeBytes: sizeBytes.toString(),
172→      })
173→      .orIgnore() // ON CONFLICT DO NOTHING for idempotency
174→      .execute();
175→  }
176→
177→  /**
178→   * Remove a pinned CID record
179→   * Idempotent - no error if CID not found
180→   */
181→  async recordUnpin(userId: string, cid: string): Promise<void> {
182→    await this.pinnedCidRepository.delete({
183→      userId,
184→      cid,
185→    });
186→  }
187→
188→  /**
189→   * Mark vault as initialized (first file uploaded)
190→   */
191→  async markInitialized(userId: string): Promise<void> {
192→    await this.vaultRepository.update({ ownerId: userId }, { initializedAt: new Date() });
193→  }
194→
195→  /**
196→   * Mark vault as migrated to v2 blob format.
197→   * Stamps migratedAt and NULLs both crypto columns
198→   * (rootFolderKey now lives in the IPFS vault blob).
199→   * Idempotent -- calling multiple times is safe.
200→   */
201→  async migrateVault(userId: string): Promise<void> {
202→    const vault = await this.vaultRepository.findOne({
203→      where: { ownerId: userId },
204→    });
205→
206→    if (!vault) {
207→      throw new NotFoundException('Vault not found');
208→    }
209→
210→    // Idempotent: if already migrated, return success
211→    if (vault.migratedAt) {
212→      return;
213→    }
214→
215→    await this.vaultRepository.update(
216→      { ownerId: userId },
217→      {
218→        migratedAt: new Date(),
219→        encryptedRootFolderKey: null,
220→        encryptedRootIpnsPrivateKey: null,
221→      }
222→    );
223→  }
224→
225→  /**
226→   * Get export data for independent recovery.
227→   * Returns the minimal set of fields needed to reconstruct the vault:
228→   * root IPNS name + encrypted root keys + derivation hints.
229→   */
230→  async getExportData(userId: string): Promise<VaultExportDto> {
231→    const vault = await this.vaultRepository.findOne({
232→      where: { ownerId: userId },
233→    });
234→
235→    if (!vault) {
236→      throw new NotFoundException('Vault not found');
237→    }
238→
239→    const user = await this.userRepository.findOne({
240→      where: { id: userId },
241→    });
242→
243→    return {
244→      format: 'cipherbox-vault-export',
245→      version: '1.0',
246→      exportedAt: new Date().toISOString(),
247→      rootIpnsName: vault.rootIpnsName,
248→      encryptedRootFolderKey: vault.encryptedRootFolderKey?.toString('hex') ?? null,
249→      encryptedRootIpnsPrivateKey: vault.encryptedRootIpnsPrivateKey?.toString('hex') ?? null,
250→      derivationMethod: user ? 'web3auth' : null,
251→    };
252→  }
253→
254→  /**
255→   * Convert Vault entity to response DTO with hex-encoded fields
256→   */
257→  private toVaultResponse(vault: Vault, teeKeys: TeeKeysDto | null = null): VaultResponseDto {
258→    return {
259→      id: vault.id,
260→      ownerPublicKey: vault.ownerPublicKey.toString('hex'),
261→      encryptedRootFolderKey: vault.encryptedRootFolderKey?.toString('hex') ?? null,
262→      encryptedRootIpnsPrivateKey: vault.encryptedRootIpnsPrivateKey?.toString('hex') ?? null,
263→      rootIpnsName: vault.rootIpnsName,
264→      createdAt: vault.createdAt,
265→      initializedAt: vault.initializedAt,
266→      migratedAt: vault.migratedAt ?? null,
267→      teeKeys,
268→    };
269→  }
270→}
