  1→//! Vault initialization and decryption commands.
  2→
  3→use crate::api::types;
  4→use crate::crypto;
  5→use crate::state::AppState;
  6→
  7→/// Initialize a new vault for a first-time user.
  8→///
  9→/// Generates a root folder AES-256 key and derives a deterministic Ed25519 IPNS
 10→/// keypair via HKDF from the user's private key. ECIES-wraps them with the
 11→/// user's secp256k1 public key, and POSTs everything to `/vault/init`.
 12→pub(crate) async fn initialize_vault(state: &AppState, public_key: &[u8]) -> Result<(), String> {
 13→    // Generate root folder AES-256 key (32 random bytes)
 14→    let root_folder_key = crypto::utils::generate_random_bytes(32);
 15→
 16→    // Derive IPNS keypair deterministically via HKDF from user's private key
 17→    let private_key = state
 18→        .private_key
 19→        .read()
 20→        .await
 21→        .as_ref()
 22→        .ok_or("Private key not available for vault IPNS derivation")?
 23→        .clone();
 24→    let private_key_arr: [u8; 32] = private_key
 25→        .as_slice()
 26→        .try_into()
 27→        .map_err(|_| "Invalid private key length")?;
 28→    let (ipns_private_key, _ipns_public_key, root_ipns_name) =
 29→        crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
 30→            .map_err(|e| format!("Vault IPNS derivation failed: {:?}", e))?;
 31→
 32→    // ECIES-wrap keys with user's uncompressed secp256k1 public key
 33→    let encrypted_root_folder_key = crypto::ecies::wrap_key(&root_folder_key, public_key)
 34→        .map_err(|e| format!("Failed to wrap root folder key: {}", e))?;
 35→    let encrypted_ipns_private_key = crypto::ecies::wrap_key(&ipns_private_key, public_key)
 36→        .map_err(|e| format!("Failed to wrap IPNS private key: {}", e))?;
 37→
 38→    // 1. Register vault with backend
 39→    let init_req = types::InitVaultRequest {
 40→        owner_public_key: hex::encode(public_key),
 41→        encrypted_root_folder_key: hex::encode(&encrypted_root_folder_key),
 42→        encrypted_root_ipns_private_key: hex::encode(&encrypted_ipns_private_key),
 43→        root_ipns_name: root_ipns_name.clone(),
 44→    };
 45→
 46→    let resp = state
 47→        .api
 48→        .authenticated_post("/vault/init", &init_req)
 49→        .await
 50→        .map_err(|e| format!("Vault init request failed: {}", e))?;
 51→
 52→    if !resp.status().is_success() {
 53→        let status = resp.status();
 54→        let body = resp.text().await.unwrap_or_default();
 55→        return Err(format!("Vault init failed ({}): {}", status, body));
 56→    }
 57→
 58→    // 2. Create and publish initial empty folder metadata
 59→    //    Without this, FUSE init() can't resolve the root IPNS name.
 60→    log::info!("Publishing initial empty root folder metadata");
 61→
 62→    let empty_metadata = crypto::folder::FolderMetadata {
 63→        version: "v2".to_string(),
 64→        children: vec![],
 65→    };
 66→
 67→    // Encrypt metadata with root folder key and produce v2 blob
 68→    let folder_key_arr: [u8; 32] = root_folder_key
 69→        .as_slice()
 70→        .try_into()
 71→        .map_err(|_| "Invalid root folder key length".to_string())?;
 72→    let sealed = crypto::folder::encrypt_folder_metadata(&empty_metadata, &folder_key_arr)
 73→        .map_err(|e| format!("Metadata encryption failed: {}", e))?;
 74→
 75→    // Format as JSON { "iv": "<hex>", "data": "<base64>" }
 76→    use base64::Engine;
 77→    let iv_hex = hex::encode(&sealed[..12]);
 78→    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
 79→    let json_metadata = serde_json::json!({
 80→        "iv": iv_hex,
 81→        "data": data_base64,
 82→    });
 83→    let json_bytes = serde_json::to_vec(&json_metadata)
 84→        .map_err(|e| format!("JSON serialization failed: {}", e))?;
 85→
 86→    // Wrap rootFolderKey in v2 blob envelope -- reuse the ECIES-wrapped key from above
 87→    let blob_bytes =
 88→        crypto::vault_blob::serialize_vault_blob_v2(&encrypted_root_folder_key, &json_bytes)?;
 89→
 90→    // Upload v2 blob to IPFS
 91→    let initial_cid = crate::api::ipfs::upload_content(&state.api, &blob_bytes).await?;
 92→
 93→    // Create and sign IPNS record (sequence 0, 24h lifetime)
 94→    let ipns_key_arr: [u8; 32] = ipns_private_key.as_slice()
 95→        .try_into()
 96→        .map_err(|_| "Invalid IPNS private key length".to_string())?;
 97→    let value = format!("/ipfs/{}", initial_cid);
 98→    let record = crypto::ipns::create_ipns_record(&ipns_key_arr, &value, 0, 86_400_000)
 99→        .map_err(|e| format!("IPNS record creation failed: {}", e))?;
100→    let marshaled = crypto::ipns::marshal_ipns_record(&record)
101→        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
102→    let record_base64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
103→
104→    // Publish IPNS record via backend (sequence 0 - first ever publish, no conflict check needed)
105→    let publish_req = crate::api::ipns::IpnsPublishRequest {
106→        ipns_name: root_ipns_name.clone(),
107→        record: record_base64,
108→        metadata_cid: initial_cid,
109→        encrypted_ipns_private_key: None,
110→        key_epoch: None,
111→        expected_sequence_number: None,
112→    };
113→    match crate::api::ipns::publish_ipns(&state.api, &publish_req).await? {
114→        crate::api::ipns::PublishResult::Success => {}
115→        crate::api::ipns::PublishResult::Conflict { .. } => {
116→            // Sequence 0 should never conflict on vault init -- log and continue
117→            log::warn!("Unexpected conflict on vault init publish (sequence 0)");
118→        }
119→    }
120→
121→    log::info!("Vault initialized and root metadata published for new user");
122→    Ok(())
123→}
124→
125→/// Fetch vault keys from backend and decrypt them using the user's private key.
126→///
127→/// Handles both migrated (v2 blob) and non-migrated (DB key) users:
128→/// - Non-migrated: decrypts rootFolderKey and IPNS key from hex in vault response
129→/// - Migrated: derives IPNS keypair via HKDF, resolves IPNS, fetches v2 blob
130→///   from IPFS, and extracts rootFolderKey from the blob header
131→///
132→/// The IPNS public key is derivable from the private key if ever needed.
133→/// Stores all keys in AppState (memory only).
134→pub(crate) async fn fetch_and_decrypt_vault(state: &AppState) -> Result<(), String> {
135→    log::info!("Fetching and decrypting vault keys");
136→
137→    // GET /vault
138→    let resp = state
139→        .api
140→        .authenticated_get("/vault")
141→        .await
142→        .map_err(|e| format!("Vault fetch failed: {}", e))?;
143→
144→    if !resp.status().is_success() {
145→        let status = resp.status();
146→        let body = resp.text().await.unwrap_or_default();
147→        return Err(format!("Vault fetch failed ({}): {}", status, body));
148→    }
149→
150→    let vault: types::VaultResponse = resp
151→        .json()
152→        .await
153→        .map_err(|e| format!("Failed to parse vault response: {}", e))?;
154→
155→    // Get private key for decryption
156→    let private_key = state
157→        .private_key
158→        .read()
159→        .await
160→        .as_ref()
161→        .ok_or("Private key not available for vault decryption")?
162→        .clone();
163→
164→    let private_key_arr: [u8; 32] = private_key
165→        .as_slice()
166→        .try_into()
167→        .map_err(|_| "Invalid private key length")?;
168→
169→    // Decrypt root folder key -- handle both migrated and non-migrated vaults
170→    let root_folder_key = if let Some(ref enc_hex) = vault.encrypted_root_folder_key {
171→        // Non-migrated: decrypt rootFolderKey from DB-stored ECIES-wrapped hex
172→        let encrypted_bytes = hex::decode(enc_hex)
173→            .map_err(|_| "Invalid encryptedRootFolderKey hex")?;
174→        crypto::ecies::unwrap_key(&encrypted_bytes, &private_key)
175→            .map_err(|e| format!("Failed to decrypt root folder key: {}", e))?
176→    } else {
177→        // Migrated (v2 blob): derive IPNS key, resolve IPNS, fetch blob, extract rootFolderKey
178→        log::info!("Vault is migrated (v2 blob) -- reading rootFolderKey from IPFS");
179→        let (_ipns_priv, _ipns_pub, ipns_name) =
180→            crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
181→                .map_err(|e| format!("HKDF derivation failed: {:?}", e))?;
182→
183→        let resolved = crate::api::ipns::resolve_ipns(&state.api, &ipns_name).await
184→            .map_err(|e| format!("IPNS resolve failed for migrated vault: {}", e))?;
185→
186→        let blob_bytes = crate::api::ipfs::fetch_content(&state.api, &resolved.cid).await
187→            .map_err(|e| format!("IPFS fetch failed for migrated vault blob: {}", e))?;
188→
189→        if crypto::vault_blob::detect_blob_version(&blob_bytes) == 2 {
190→            let (enc_key, _meta) = crypto::vault_blob::deserialize_vault_blob_v2(&blob_bytes)
191→                .map_err(|e| format!("v2 blob parse failed: {}", e))?;
192→            crypto::ecies::unwrap_key(enc_key, &private_key)
193→                .map_err(|e| format!("Failed to decrypt rootFolderKey from v2 blob: {}", e))?
194→        } else {
195→            return Err("Migrated vault but IPNS blob is not v2 format".into());
196→        }
197→    };
198→    *state.root_folder_key.write().await = Some(root_folder_key);
199→
200→    // Decrypt root IPNS private key -- handle both migrated and non-migrated
201→    let root_ipns_private_key = if let Some(ref enc_hex) = vault.encrypted_root_ipns_private_key {
202→        // Non-migrated: decrypt from DB-stored ECIES-wrapped hex
203→        let encrypted_bytes = hex::decode(enc_hex)
204→            .map_err(|_| "Invalid encryptedRootIpnsPrivateKey hex")?;
205→        let decrypted = crypto::ecies::unwrap_key(&encrypted_bytes, &private_key)
206→            .map_err(|e| format!("Failed to decrypt root IPNS private key: {}", e))?;
207→
208→        // Verify stored IPNS key matches HKDF derivation (consistency check)
209→        if let Ok((expected_ipns_key, _, _)) = crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr) {
210→            if decrypted != *expected_ipns_key {
211→                log::warn!("Vault IPNS key mismatch: stored key differs from HKDF derivation");
212→                // Don't block - proceed with stored key for backward compatibility
213→            }
214→        }
215→        decrypted
216→    } else {
217→        // Migrated or new user: use HKDF-derived IPNS key directly
218→        log::info!("Using HKDF-derived IPNS key (no stored key)");
219→        let (ipns_priv, _, _) = crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
220→            .map_err(|e| format!("HKDF derivation failed: {:?}", e))?;
221→        ipns_priv.to_vec()
222→    };
223→
224→    *state.root_ipns_private_key.write().await = Some(root_ipns_private_key);
225→
226→    // Store IPNS name and TEE keys
227→    *state.root_ipns_name.write().await = Some(vault.root_ipns_name);
228→    *state.tee_keys.write().await = vault.tee_keys;
229→
230→    log::info!("Vault keys decrypted and stored in memory");
231→    Ok(())
232→}
