 37→import { addToIpfs, fetchFromIpfs } from '../lib/api/ipfs';
 38→
 39→export function useAuth() {
 40→  const navigate = useNavigate();
 41→  const {
 42→    isLoggedIn: coreKitLoggedIn,
 43→    isInitialized: coreKitInitialized,
 44→    isRequiredShare,
 45→    loginWithGoogle: coreKitLoginGoogle,
 46→    loginWithEmailOtp: coreKitLoginEmail,
 47→    loginWithWallet: coreKitLoginWallet,
 48→    getVaultKeypair,
 49→    getPublicKeyHex,
 50→    logout: coreKitLogout,
 51→  } = useCoreKitAuth();
 52→  const { syncStatus } = useCoreKit();
 53→  const {
 54→    accessToken,
 55→    isAuthenticated,
 56→    lastAuthMethod,
 57→    userEmail,
 58→    setAccessToken,
 59→    setAuthenticated,
 60→    setLastAuthMethod,
 61→    setUserEmail,
 62→    setVaultKeypair,
 63→  } = useAuthStore();
 64→
 65→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 66→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 67→  const restoringRef = useRef(false);
 68→
 69→  // Stable refs for functions used in the session restoration effect.
 70→  // This prevents the effect from re-firing when function references change.
 71→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 72→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 73→
 74→  // Pending auth state for REQUIRED_SHARE flow.
 75→  // Stored in Zustand (not useState) so the state is shared across all
 76→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 77→  // via its own useAuth() call.
 78→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 79→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 80→
 81→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 82→
 83→  // Get vault store actions
 84→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 85→
 86→  /**
 87→   * Initialize vault for new users or load existing vault keys.
 88→   * Called after successful backend authentication.
 89→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 90→   */
 91→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 92→    // Get user's secp256k1 keypair from Core Kit TSS export
 93→    const userKeypair = await getVaultKeypair();
 94→
 95→    if (!userKeypair) {
 96→      throw new Error('Failed to get vault keypair from Core Kit');
 97→    }
 98→
 99→    // Store keypair in auth store for crypto operations
100→    setVaultKeypair(userKeypair);
101→
102→    try {
103→      // Try to fetch existing vault
104→      const existingVault = await vaultApi.getVault();
105→
106→      // Store TEE keys if available
107→      if (existingVault.teeKeys) {
108→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
109→      }
110→
111→      if (existingVault.migratedAt) {
112→        // PATH A: Migrated user -- read rootFolderKey from IPFS v2 blob
113→        // Derive IPNS keypair once (used for both resolution and vault keys)
114→        const ipnsKeypair = await deriveVaultIpnsKeypair(userKeypair.privateKey);
115→        let rootFolderKey: Uint8Array;
116→        try {
117→          const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);
118→
119→          // Resolve IPNS to CID using the existing IPNS service (handles signature verification)
120→          const resolved = await resolveIpnsRecord(ipnsName);
121→          if (!resolved) throw new Error('IPNS name not found for migrated vault');
122→
123→          // Fetch blob bytes from IPFS using the existing IPFS adapter
124→          const blobBytes = await fetchFromIpfs(resolved.cid);
125→
126→          if (detectBlobVersion(blobBytes) === 2) {
127→            const { encryptedRootFolderKey: encKey } = deserializeVaultBlobV2(blobBytes);
128→            rootFolderKey = await unwrapKey(encKey, userKeypair.privateKey);
129→          } else {
130→            throw new Error('Migrated vault but IPNS blob is v1 format');
131→          }
132→        } catch (ipfsError) {
133→          // Silent DB fallback for migrated users (per CONTEXT decision)
134→          console.warn('[Auth] v2 blob read failed, falling back to DB:', ipfsError);
135→          if (existingVault.encryptedRootFolderKey) {
136→            rootFolderKey = await unwrapKey(
137→              hexToBytes(existingVault.encryptedRootFolderKey as unknown as string),
138→              userKeypair.privateKey
139→            );
140→          } else {
141→            // DB fields are null and IPFS failed -- cannot recover
142→            throw new Error('Migrated vault: IPFS read failed and no DB fallback available');
143→          }
144→        }
145→
146→        setVaultKeys({
147→          rootFolderKey,
148→          rootIpnsKeypair: ipnsKeypair,
149→          rootIpnsName: existingVault.rootIpnsName,
150→          vaultId: existingVault.id,
151→        });
152→      } else {
153→        // PATH B: Non-migrated existing user -- decrypt from DB + trigger migration
154→        const decryptedVault = await decryptVaultKeys(
155→          {
156→            encryptedRootFolderKey: hexToBytes(
157→              existingVault.encryptedRootFolderKey as unknown as string
158→            ),
159→            encryptedIpnsPrivateKey: hexToBytes(
160→              existingVault.encryptedRootIpnsPrivateKey as unknown as string
161→            ),
162→          },
163→          userKeypair.privateKey
164→        );
165→
166→        setVaultKeys({
167→          rootFolderKey: decryptedVault.rootFolderKey,
168→          rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
169→          rootIpnsName: existingVault.rootIpnsName,
170→          vaultId: existingVault.id,
171→        });
172→
173→        // Non-blocking migration trigger: write v2 blob + call /vault/migrate
174→        void (async () => {
175→          try {
176→            // 1. ECIES-wrap rootFolderKey with user's publicKey
177→            const encryptedKey = await wrapKey(decryptedVault.rootFolderKey, userKeypair.publicKey);
178→
179→            // 2. Resolve current IPNS to get existing blob and sequence number
180→            const ipnsName = existingVault.rootIpnsName;
181→            const resolved = await resolveIpnsRecord(ipnsName);
182→            if (!resolved) throw new Error('IPNS name not found during migration');
183→            const currentSeqNo = resolved.sequenceNumber;
184→
185→            // 3. Fetch current blob (v1 JSON metadata)
186→            const existingMetadataJson = await fetchFromIpfs(resolved.cid);
187→
188→            // 4. Serialize as v2 blob
189→            const v2Blob = serializeVaultBlobV2(encryptedKey, existingMetadataJson);
190→
191→            // 5. Upload v2 blob to IPFS
192→            const uploadResult = await addToIpfs(new Blob([v2Blob as BlobPart]));
193→
194→            // 6. Derive HKDF keypair and publish IPNS record with seq+1
195→            const ipnsKeypair = await deriveVaultIpnsKeypair(userKeypair.privateKey);
196→            const publishResult = await createAndPublishIpnsRecord({
197→              ipnsPrivateKey: ipnsKeypair.privateKey,
198→              ipnsName,
199→              metadataCid: uploadResult.cid,
200→              sequenceNumber: currentSeqNo + 1n,
201→              expectedSequenceNumber: currentSeqNo.toString(),
202→            });
203→
204→            if (!publishResult.success) {
205→              throw new Error('IPNS publish failed during vault migration');
206→            }
207→
208→            // 7. Stamp migratedAt and NULL DB columns (only after confirmed write)
209→            await vaultControllerMigrateVault();
210→            console.log('[Auth] Vault successfully migrated to v2 blob format');
211→          } catch (migrationError) {
212→            // Migration failure is non-blocking. User can still use the app.
213→            // Migration will be retried on next login.
214→            console.warn(
215→              '[Auth] Vault v2 migration failed (will retry on next login):',
216→              migrationError
217→            );
218→          }
219→        })();
220→      }
221→    } catch (error) {
222→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
223→
224→      if (is404) {
225→        // New user - initialize vault
226→        console.log(
227→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
228→        );
229→        const newVault = await initializeVault(userKeypair.privateKey);
230→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
231→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
232→
233→        const storedVault = await vaultApi.initVault({
234→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
235→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
236→          // encryptedRootIpnsPrivateKey omitted -- HKDF derivation is canonical (VAULT-04)
237→          rootIpnsName,
238→        });
239→
240→        if (storedVault.teeKeys) {
241→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
242→        }
243→
244→        setVaultKeys({
245→          rootFolderKey: newVault.rootFolderKey,
246→          rootIpnsKeypair: newVault.rootIpnsKeypair,
247→          rootIpnsName,
248→          vaultId: storedVault.id,
249→          isNewVault: true,
250→        });
251→      } else {
252→        console.error('[useAuth] Failed to load vault:', error);
253→        throw error;
254→      }
255→    }
256→
257→    // Initialize SDK client with decrypted vault keys
258→    const vaultState = useVaultStore.getState();
259→    const authState = useAuthStore.getState();
260→    if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
261→      const apiUrl = import.meta.env.VITE_API_URL || window.location.origin + '/api';
262→      const getAccessToken = async () => {
263→        const state = useAuthStore.getState();
264→        return state.accessToken || '';
265→      };
266→
267→      // @cipherbox/api-client is configured in lib/api-config.ts at module load time.
268→
269→      const sdkClient = initSdkClient({
270→        apiUrl,
271→        getAccessToken,
272→        vaultKeypair: {
273→          publicKey: userKeypair.publicKey,
274→          privateKey: userKeypair.privateKey,
275→        },
276→        rootIpnsName: vaultState.rootIpnsName,
277→        rootFolderKey: vaultState.rootFolderKey,
278→        teeKeys: authState.teeKeys ?? undefined,
279→        shareCallbacks: {
280→          getCoveringShares: async (folderIpnsName: string) => {
281→            const { findCoveringShares } = await import('../services/share.service');
282→            const folders = useFolderStore.getState().folders;
283→            // Find the folder ID from IPNS name for ancestor traversal
284→            const folderId =
285→              Object.keys(folders).find((id) => folders[id].ipnsName === folderIpnsName) ?? null;
286→            return findCoveringShares(folderIpnsName, folders, folderId);
287→          },
288→          addShareKeys: async (shareId, keys) => {
289→            const { addShareKeys } = await import('../services/share.service');
290→            await addShareKeys(shareId, keys);
291→          },
292→        },
293→      });
294→
295→      // Subscribe folder store to SDK events
296→      useFolderStore.getState().subscribeToSdk(sdkClient);
297→
298→      // Subscribe bin store to SDK events
299→      useBinStore.getState().subscribeToSdk(sdkClient);
300→    }
301→
302→    // Non-blocking device registry initialization (fire-and-forget)
303→    // Placed after vault load so registry failures never block login
304→    void (async () => {
305→      try {
306→        const deviceKeypair = await getOrCreateDeviceIdentity({
307→          mode: 'persisted',
308→          vaultPrivateKey: userKeypair.privateKey,
309→        });
310→        const deviceInfo = detectDeviceInfo();
311→        const result = await initializeOrSyncRegistry({
312→          userPrivateKey: userKeypair.privateKey,
313→          userPublicKey: userKeypair.publicKey,
314→          deviceKeypair,
315→          deviceInfo: { ...deviceInfo, ipHash: '' },
316→        });
317→        if (result) {
318→          useDeviceRegistryStore
319→            .getState()
320→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
321→        }
322→      } catch (error) {
323→        console.error('[Auth] Device registry init failed (non-blocking):', error);
324→      }
325→    })();
326→
327→    // Non-blocking bin initialization (fire-and-forget)
328→    // After old service creates/loads bin, also load into SDK for deleteToBin support
329→    void (async () => {
330→      try {
331→        await initializeBin({
332→          userPrivateKey: userKeypair.privateKey,
333→          userPublicKey: userKeypair.publicKey,
334→        });
335→        // Now load bin into SDK (old service ensures bin IPNS record exists)
336→        const { getSdkClient, hasSdkClient } = await import('../lib/sdk-provider');
337→        if (hasSdkClient()) {
338→          await getSdkClient().loadBin();
339→        }
340→      } catch (error) {
341→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
342→      }
343→    })();
344→
345→    // Non-blocking: fetch retention config from API
346→    void (async () => {
347→      try {
348→        const config = await vaultControllerGetConfig();
349→        if (config.recycleBinRetentionDays != null) {
350→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
351→        }
352→      } catch (error) {
353→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
354→      }
355→    })();
356→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
357→
358→  /**
359→   * Complete backend authentication after Core Kit login.
360→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
361→   * to the backend with loginType 'corekit'. The backend verifies it against
362→   * its own JWKS since CipherBox is the identity provider.
363→   */
364→  const completeBackendAuth = useCallback(
365→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
366→      // 1. Get real publicKey from Core Kit TSS export
367→      const publicKey = await getPublicKeyHex();
368→      if (!publicKey) {
369→        throw new Error('Failed to get publicKey from Core Kit');
370→      }
371→
372→      // publicKey available for debugging via DevTools if needed
373→
374→      // 2. Authenticate with CipherBox backend
375→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
376→      const response = await authApi.login({
377→        idToken: cipherboxJwt,
378→        publicKey,
379→        loginType: 'corekit',
380→      });
381→
382→      // 3. Store access token (refresh token in HTTP-only cookie)
383→      // Note: this does NOT set isAuthenticated — we wait until vault + SDK
384→      // are fully initialized to prevent Login.tsx from redirecting to /files
385→      // before the SDK client is ready for file operations.
386→      setAccessToken(response.accessToken);
387→
388→      // 4. Remember auth method for UX
389→      setLastAuthMethod(authMethod);
390→
391→      // 5. Initialize or load vault + SDK client
392→      await initializeOrLoadVault();
393→
394→      // 6. Now that vault keys are loaded and SDK is initialized,
395→      // mark the user as authenticated. This triggers Login.tsx → /files redirect.
396→      setAuthenticated();
397→    },
398→    [getPublicKeyHex, setAccessToken, setAuthenticated, setLastAuthMethod, initializeOrLoadVault]
399→  );
400→
401→  /**
402→   * Complete the login flow after REQUIRED_SHARE is resolved.
403→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
404→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
405→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
406→   */
407→  const completeRequiredShare = useCallback(async (): Promise<void> => {
408→    // Read directly from Zustand store to get fresh values — this callback
409→    // may be called from useDeviceApproval's useAuth() instance, so we
410→    // can't rely on closure-captured selector values.
411→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
412→
413→    if (!jwt || !method) {
414→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
415→    }
416→
417→    // Core Kit should now be LOGGED_IN after inputFactorKey()
418→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
419→    await completeBackendAuth(method, jwt);
420→
421→    // NOW sync Core Kit React state to LOGGED_IN.
422→    // We deliberately delayed this from inputFactorKey() to prevent the session
423→    // restoration effect from firing before backend auth completed.
424→    // At this point isAuthenticated is true (from completeBackendAuth -> setAuthenticated),
425→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
426→    syncStatus();
427→
428→    // Clear pending state
429→    setPendingAuth(null, null);
430→
431→    // Navigate to files
432→    navigate('/files');
433→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
434→
435→  /**
436→   * Login with Google OAuth token.
437→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
438→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
439→   */
440→  const loginWithGoogle = useCallback(
441→    async (googleIdToken: string): Promise<void> => {
442→      if (isLoggingIn) return;
443→      setIsLoggingIn(true);
444→      try {
445→        // 1. Core Kit login via CipherBox identity provider
446→        const {
447→          cipherboxJwt,
448→          email,
449→          userId,
450→          status: coreKitStatus,
451→        } = await coreKitLoginGoogle(googleIdToken);
452→
453→        if (coreKitStatus === 'required_share') {
454→          // MFA enabled but device factor missing.
455→          // Store pending auth info for later completion after factor input.
456→          setPendingAuth(cipherboxJwt, 'google');
457→
458→          // Obtain temporary backend access token so the new device can
459→          // call bulletin board API endpoints (device-approval/*).
460→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
461→          // state and we can't export the TSS key yet.
462→          const tempLoginResponse = await authApi.login({
463→            idToken: cipherboxJwt,
464→            publicKey: `pending-core-kit-${userId}`,
465→            loginType: 'corekit',
466→          });
467→          setAccessToken(tempLoginResponse.accessToken);
468→
469→          if (email) {
470→            setUserEmail(email);
471→          }
472→
473→          // Do NOT call completeBackendAuth() or navigate('/files')
474→          // The component tree will see isRequiredShare === true and
475→          // render recovery/approval UI.
476→          return;
477→        }
478→
479→        // Normal path: Core Kit logged in, proceed as before
480→        // 2. Complete backend auth + vault init
481→        await completeBackendAuth('google', cipherboxJwt);
482→
483→        // 3. Store email for UI display (returned from identity endpoint)
484→        if (email) {
485→          setUserEmail(email);
486→        }
487→
488→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
489→      } catch (error) {
490→        console.error('[useAuth] Google login failed:', error);
491→        throw error;
492→      } finally {
493→        setIsLoggingIn(false);
494→      }
495→    },
496→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
497→  );
498→
499→  /**
500→   * Login with Email OTP.
501→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
502→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
503→   */
504→  const loginWithEmail = useCallback(
505→    async (email: string, otp: string): Promise<void> => {
506→      if (isLoggingIn) return;
507→      setIsLoggingIn(true);
508→      try {
509→        // 1. Core Kit login via CipherBox identity provider
510→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
511→
512→        if (coreKitStatus === 'required_share') {
513→          setPendingAuth(cipherboxJwt, 'email');
514→
515→          const tempLoginResponse = await authApi.login({
516→            idToken: cipherboxJwt,
517→            publicKey: `pending-core-kit-${userId}`,
518→            loginType: 'corekit',
519→          });
520→          setAccessToken(tempLoginResponse.accessToken);
521→          setUserEmail(email);
522→          return;
523→        }
524→
525→        // Normal path
526→        await completeBackendAuth('email', cipherboxJwt);
527→        setUserEmail(email);
528→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
529→      } catch (error) {
530→        console.error('[useAuth] Email login failed:', error);
531→        throw error;
532→      } finally {
533→        setIsLoggingIn(false);
534→      }
535→    },
536→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
537→  );
538→
539→  /**
540→   * Login with Wallet (SIWE).
541→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
542→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
543→   */
544→  const loginWithWallet = useCallback(
545→    async (cipherboxJwt: string, userId: string): Promise<void> => {
546→      if (isLoggingIn) return;
547→      setIsLoggingIn(true);
548→      try {
549→        // 1. Core Kit login via CipherBox identity provider
550→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
551→
552→        if (coreKitStatus === 'required_share') {
553→          setPendingAuth(cipherboxJwt, 'wallet');
554→
555→          const tempLoginResponse = await authApi.login({
556→            idToken: cipherboxJwt,
557→            publicKey: `pending-core-kit-${userId}`,
558→            loginType: 'corekit',
559→          });
560→          setAccessToken(tempLoginResponse.accessToken);
561→          return;
562→        }
563→
564→        // Normal path
565→        await completeBackendAuth('wallet', cipherboxJwt);
566→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
567→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
568→        // inside it may still be pending. An explicit navigate here would fire AFTER
569→        // vault init completes — by which point the user may have navigated away from
570→        // the login page, causing a disruptive late redirect.
571→      } catch (error) {
572→        console.error('[useAuth] Wallet login failed:', error);
573→        throw error;
574→      } finally {
575→        setIsLoggingIn(false);
576→      }
577→    },
578→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
579→  );
580→
581→  // Complete logout: Backend -> Core Kit -> Clear state
582→  const logout = useCallback(async () => {
583→    if (isLoggingOut) return;
584→
585→    setIsLoggingOut(true);
586→    try {
587→      // 1. Call backend logout (clears cookie)
588→      if (accessToken) {
589→        try {
590→          await authApi.logout();
591→        } catch {
592→          // Ignore errors -- we'll clear state anyway
593→        }
594→      }
595→
596→      // 2. Logout Core Kit (clears session from localStorage)
597→      await coreKitLogout();
598→
599→      // 3. Clear all user-scoped stores (centralized helper)
600→      clearAllUserStores();
601→
602→      // 4. Navigate to login
603→      navigate('/');
604→    } catch (error) {
605→      console.error('[useAuth] Logout failed:', error);
606→      // Still clear state even if backend fails
607→      clearAllUserStores();
608→      navigate('/');
609→    } finally {
610→      setIsLoggingOut(false);
611→    }
612→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
613→
614→  // Keep function refs up-to-date for use in session restoration effect.
615→  // Using refs prevents the effect from re-firing when function identities change.
616→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
617→  coreKitLogoutRef.current = coreKitLogout;
618→
619→  // Session restoration: if Core Kit restores a session from localStorage
620→  // on init, we have LOGGED_IN status without going through login flow.
621→  // Complete backend auth + vault loading.
622→  useEffect(() => {
623→    const restoreSession = async () => {
624→      // Only restore if Core Kit has a session but we don't have
625→      // a backend access token yet
626→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
627→        restoringRef.current = true;
628→        setIsLoggingIn(true);
629→        try {
630→          // Try to refresh using the HTTP-only cookie first
631→          const response = await authApi.refresh();
632→          setAccessToken(response.accessToken);
633→
634→          // Restore email from backend if available
635→          if (response.email) {
636→            setUserEmail(response.email);
637→          }
638→
639→          // Load vault keys from Core Kit keypair + initialize SDK
640→          await initializeOrLoadVaultRef.current?.();
641→
642→          // Mark as authenticated only after vault + SDK are ready
643→          setAuthenticated();
644→        } catch {
645→          // No valid backend session -- user needs to re-login
646→          // Core Kit session exists but backend cookie expired
647→          // Clear Core Kit session to avoid inconsistent state
648→          try {
649→            await coreKitLogoutRef.current?.();
650→          } catch {
651→            // Ignore logout errors during cleanup
652→          }
653→        } finally {
654→          restoringRef.current = false;
655→          setIsLoggingIn(false);
656→        }
657→      }
658→    };
659→    restoreSession();
660→  }, [
661→    coreKitLoggedIn,
662→    isAuthenticated,
663→    isLoggingIn,
664→    setAccessToken,
665→    setAuthenticated,
666→    setUserEmail,
667→  ]);
668→
669→  return {
670→    isLoading,
671→    isAuthenticated,
672→    isRequiredShare,
673→    lastAuthMethod,
674→    userEmail,
675→    pendingAuthMethod,
676→    loginWithGoogle,
677→    loginWithEmail,
678→    loginWithWallet,
679→    completeRequiredShare,
680→    logout,
681→  };
682→}
683→

  1→/**
  2→ * @cipherbox/core - Vault Blob v2 Format
  3→ *
  4→ * Binary envelope format for storing ECIES-encrypted rootFolderKey alongside
  5→ * AES-GCM encrypted folder metadata in a single IPFS blob.
  6→ *
  7→ * Format: 0x02 | uint16_BE(key_len) | encrypted_key | encrypted_metadata_json
  8→ *
  9→ * This module is pure byte manipulation with zero external dependencies
 10→ * (beyond types), making it easy to verify and port to other languages (Rust).
 11→ *
 12→ * Cross-platform test vectors in vault-blob-vectors.test.ts ensure binary
 13→ * compatibility between TypeScript and Rust implementations.
 14→ */
 15→
 16→import type { VaultBlobV2 } from './types';
 17→
 18→/** Version byte for vault blob v2 format */
 19→export const BLOB_V2_VERSION = 0x02;
 20→
 21→/**
 22→ * Detect whether a vault blob is v1 (JSON) or v2 (binary envelope).
 23→ *
 24→ * v1 blobs start with 0x7B ('{' -- JSON object).
 25→ * v2 blobs start with 0x02 (version byte).
 26→ *
 27→ * Any blob that does not start with 0x02 is treated as v1 for backward
 28→ * compatibility -- this includes malformed blobs, which will fail at
 29→ * the JSON parse stage.
 30→ *
 31→ * @param blob - Raw bytes from IPFS
 32→ * @returns 1 for v1 JSON blobs, 2 for v2 binary blobs
 33→ */
 34→export function detectBlobVersion(blob: Uint8Array): 1 | 2 {
 35→  return blob.length > 0 && blob[0] === BLOB_V2_VERSION ? 2 : 1;
 36→}
 37→
 38→/**
 39→ * Serialize vault blob v2.
 40→ *
 41→ * Constructs a binary envelope:
 42→ *   byte 0:    version (0x02)
 43→ *   bytes 1-2: key_len as big-endian uint16
 44→ *   bytes 3..: encrypted rootFolderKey (key_len bytes)
 45→ *   remaining: encrypted metadata JSON
 46→ *
 47→ * @param encryptedRootFolderKey - ECIES-wrapped rootFolderKey (typically 129 bytes)
 48→ * @param encryptedMetadataJson - AES-GCM encrypted folder metadata JSON
 49→ * @returns Complete v2 blob ready for IPFS storage
 50→ */
 51→export function serializeVaultBlobV2(
 52→  encryptedRootFolderKey: Uint8Array,
 53→  encryptedMetadataJson: Uint8Array
 54→): Uint8Array {
 55→  const keyLen = encryptedRootFolderKey.length;
 56→  if (keyLen > 0xffff) {
 57→    throw new Error(`Encrypted key too long for v2 blob (${keyLen} bytes, max ${0xffff})`);
 58→  }
 59→  const totalLen = 3 + keyLen + encryptedMetadataJson.length;
 60→  const result = new Uint8Array(totalLen);
 61→
 62→  // Version byte
 63→  result[0] = BLOB_V2_VERSION;
 64→  // Key length as big-endian uint16
 65→  result[1] = (keyLen >> 8) & 0xff;
 66→  result[2] = keyLen & 0xff;
 67→  // ECIES-encrypted rootFolderKey
 68→  result.set(encryptedRootFolderKey, 3);
 69→  // AES-GCM encrypted metadata JSON
 70→  result.set(encryptedMetadataJson, 3 + keyLen);
 71→
 72→  return result;
 73→}
 74→
 75→/**
 76→ * Deserialize vault blob v2 into its components.
 77→ *
 78→ * Validates the version byte and key_len field, then slices the blob
 79→ * into its two components.
 80→ *
 81→ * @param blob - Complete v2 blob from IPFS
 82→ * @returns Parsed components: encryptedRootFolderKey and encryptedMetadataJson
 83→ * @throws Error if blob is not v2 format, truncated, or key_len overflows
 84→ */
 85→export function deserializeVaultBlobV2(blob: Uint8Array): VaultBlobV2 {
 86→  if (blob.length < 3) {
 87→    throw new Error('Vault blob too short for v2 header (need at least 3 bytes)');
 88→  }
 89→
 90→  if (blob[0] !== BLOB_V2_VERSION) {
 91→    throw new Error('Not a v2 vault blob');
 92→  }
 93→
 94→  const keyLen = (blob[1] << 8) | blob[2];
 95→
 96→  if (blob.length < 3 + keyLen) {
 97→    throw new Error(
 98→      `Vault blob too short for key (expected ${keyLen} bytes, have ${blob.length - 3})`
 99→    );
100→  }
101→
102→  return {
103→    encryptedRootFolderKey: blob.slice(3, 3 + keyLen),
104→    encryptedMetadataJson: blob.slice(3 + keyLen),
105→  };
106→}
107→

  1→/**
  2→ * IPNS Service - Record creation, publishing, and resolution
  3→ *
  4→ * Creates IPNS records locally using @cipherbox/core and publishes
  5→ * via the backend API relay to the delegated routing service.
  6→ */
  7→
  8→import { createIpnsRecord, marshalIpnsRecord, IPNS_SIGNATURE_PREFIX } from '@cipherbox/core';
  9→import { verifyEd25519, concatBytes } from '@cipherbox/crypto';
 10→import {
 11→  ipnsControllerPublishRecord,
 12→  ipnsControllerPublishBatch,
 13→  ipnsControllerResolveRecord,
 14→} from '@cipherbox/api-client';
 15→import type { PublishIpnsEntryDtoRecordType } from '@cipherbox/api-client';
 16→
 17→/**
 18→ * Create an IPNS record locally and publish via backend.
 19→ *
 20→ * The record is signed locally using the Ed25519 private key, then
 21→ * the backend relays it to the IPFS network via delegated routing.
 22→ *
 23→ * @param params.ipnsPrivateKey - Ed25519 private key (64 bytes in libp2p format)
 24→ * @param params.ipnsName - IPNS name (k51.../bafzaa... format)
 25→ * @param params.metadataCid - CID of the encrypted metadata blob
 26→ * @param params.sequenceNumber - Current sequence number (will be incremented before publish)
 27→ * @param params.encryptedIpnsPrivateKey - Hex ECIES-wrapped key for TEE (first publish only)
 28→ * @param params.keyEpoch - TEE key epoch (required with encryptedIpnsPrivateKey)
 29→ * @param params.expectedSequenceNumber - Pre-increment sequence number for conflict detection (folder records only)
 30→ */
 31→export async function createAndPublishIpnsRecord(params: {
 32→  ipnsPrivateKey: Uint8Array;
 33→  ipnsName: string;
 34→  metadataCid: string;
 35→  sequenceNumber: bigint;
 36→  encryptedIpnsPrivateKey?: string;
 37→  keyEpoch?: number;
 38→  expectedSequenceNumber?: string;
 39→}): Promise<{ success: boolean; sequenceNumber: bigint }> {
 40→  // 1. Create IPNS record pointing to /ipfs/{metadataCid}
 41→  // 24 hour lifetime (will be republished by TEE every 3 hours)
 42→  const record = await createIpnsRecord(
 43→    params.ipnsPrivateKey,
 44→    `/ipfs/${params.metadataCid}`,
 45→    params.sequenceNumber,
 46→    24 * 60 * 60 * 1000 // 24 hours in ms
 47→  );
 48→
 49→  // 2. Marshal to bytes for transport
 50→  const recordBytes = marshalIpnsRecord(record);
 51→
 52→  // 3. Base64 encode for API transmission
 53→  const recordBase64 = btoa(String.fromCharCode(...recordBytes));
 54→
 55→  // 4. Call backend API to relay to IPFS network
 56→  const response = await ipnsControllerPublishRecord({
 57→    ipnsName: params.ipnsName,
 58→    record: recordBase64,
 59→    metadataCid: params.metadataCid,
 60→    encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
 61→    keyEpoch: params.keyEpoch,
 62→    expectedSequenceNumber: params.expectedSequenceNumber,
 63→  });
 64→
 65→  return {
 66→    success: response.success,
 67→    sequenceNumber: BigInt(response.sequenceNumber),
 68→  };
 69→}
 70→
 71→/**
 72→ * Batch publish multiple IPNS records in a single API call.
 73→ *
 74→ * Sends all records (folder and/or file) to the batch endpoint,
 75→ * which processes them with concurrency-limited parallelism.
 76→ * Partial success is allowed: individual failures do not fail the batch.
 77→ *
 78→ * @param records - Array of IPNS record payloads to publish
 79→ * @returns Success and failure counts
 80→ */
 81→export async function batchPublishIpnsRecords(
 82→  records: Array<{
 83→    ipnsName: string;
 84→    recordBase64: string;
 85→    metadataCid: string;
 86→    encryptedIpnsPrivateKey?: string;
 87→    keyEpoch?: number;
 88→    recordType?: 'folder' | 'file';
 89→    /** Pre-increment sequence number for conflict detection (folder records only) */
 90→    expectedSequenceNumber?: string;
 91→  }>
 92→): Promise<{ totalSucceeded: number; totalFailed: number }> {
 93→  const response = await ipnsControllerPublishBatch({
 94→    records: records.map((r) => ({
 95→      ipnsName: r.ipnsName,
 96→      record: r.recordBase64,
 97→      metadataCid: r.metadataCid,
 98→      encryptedIpnsPrivateKey: r.encryptedIpnsPrivateKey,
 99→      keyEpoch: r.keyEpoch,
100→      recordType: r.recordType as PublishIpnsEntryDtoRecordType | undefined,
101→      expectedSequenceNumber: r.expectedSequenceNumber,
102→    })),
103→  });
104→
105→  return {
106→    totalSucceeded: response.totalSucceeded,
107→    totalFailed: response.totalFailed,
108→  };
109→}
110→
111→/**
112→ * Verify the Ed25519 signature on an IPNS record.
113→ * Per IPFS spec, the signature is over "ipns-signature:" + cborData.
114→ *
115→ * @param signatureV2 - base64 Ed25519 signature (64 bytes)
116→ * @param data - base64 CBOR data that was signed
117→ * @param pubKey - base64 raw Ed25519 public key (32 bytes)
118→ * @returns true if valid
119→ */
120→export async function verifyIpnsSignature(
121→  signatureV2: string,
122→  data: string,
123→  pubKey: string
124→): Promise<boolean> {
125→  const sigBytes = Uint8Array.from(atob(signatureV2), (c) => c.charCodeAt(0));
126→  const dataBytes = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
127→  const pubKeyBytes = Uint8Array.from(atob(pubKey), (c) => c.charCodeAt(0));
128→
129→  // Per IPFS IPNS spec, signature is over "ipns-signature:" + cborData
130→  const signedData = concatBytes(IPNS_SIGNATURE_PREFIX, dataBytes);
131→  return verifyEd25519(sigBytes, signedData, pubKeyBytes);
132→}
133→
134→/**
135→ * Resolve an IPNS name to its current CID and sequence number.
136→ *
137→ * Calls backend API which relays to the delegated routing service for resolution.
138→ * When the response includes IPNS signature data (from delegated routing),
139→ * verifies the Ed25519 signature before trusting the CID.
140→ *
141→ * @param ipnsName - IPNS name to resolve (k51.../bafzaa... format)
142→ * @returns Current CID, sequence number, and signature verification status, or null if not found
143→ */
144→export async function resolveIpnsRecord(
145→  ipnsName: string
146→): Promise<{ cid: string; sequenceNumber: bigint; signatureVerified: boolean } | null> {
147→  try {
148→    const response = await ipnsControllerResolveRecord({ ipnsName });
149→
150→    if (!response.success) {
151→      return null;
152→    }
153→
154→    // Verify IPNS signature if all signature fields are present
155→    let signatureVerified = false;
156→    if (response.signatureV2 && response.data && response.pubKey) {
157→      const valid = await verifyIpnsSignature(response.signatureV2, response.data, response.pubKey);
158→      if (!valid) {
159→        throw new Error('IPNS signature verification failed - record may be tampered');
160→      }
161→      signatureVerified = true;
162→    } else {
163→      console.warn('IPNS resolve returned without signature data, skipping verification');
164→    }
165→
166→    return {
167→      cid: response.cid,
168→      sequenceNumber: BigInt(response.sequenceNumber),
169→      signatureVerified,
170→    };
171→  } catch (error) {
172→    // 404 means IPNS name not found - return null
173→    // Other errors should propagate (including signature verification failures)
174→    if (error instanceof Error && (error as Error & { status?: number }).status === 404) {
175→      return null;
176→    }
177→    throw error;
178→  }
179→}
180→

 1→/**
 2→ * IPFS API adapter -- wraps @cipherbox/api-client generated functions
 3→ * with upload progress tracking, cancel support, and download-as-Uint8Array.
 4→ *
 5→ * Progress callbacks are passed via the axios options parameter
 6→ * (onUploadProgress / onDownloadProgress) to the generated functions.
 7→ */
 8→import {
 9→  ipfsControllerUpload,
10→  ipfsControllerUnpin,
11→  ipfsControllerGet,
12→} from '@cipherbox/api-client';
13→import type { AxiosProgressEvent, CancelToken } from '@cipherbox/api-client';
14→
15→export type AddResponse = { cid: string; size: number; recorded: boolean };
16→
17→export type DownloadProgressCallback = (loaded: number, total: number) => void;
18→
19→/**
20→ * Upload encrypted file to IPFS via backend relay.
21→ * Uses axios for upload progress tracking and cancellation.
22→ */
23→export async function addToIpfs(
24→  encryptedFile: Blob,
25→  onProgress?: (percent: number) => void,
26→  cancelToken?: CancelToken
27→): Promise<AddResponse> {
28→  const result = await ipfsControllerUpload(
29→    { file: encryptedFile },
30→    {
31→      ...(onProgress && {
32→        onUploadProgress: (event: AxiosProgressEvent) => {
33→          if (event.total) {
34→            onProgress(Math.round((event.loaded * 100) / event.total));
35→          }
36→        },
37→      }),
38→      cancelToken,
39→    }
40→  );
41→
42→  return { cid: result.cid, size: result.size, recorded: result.recorded };
43→}
44→
45→/**
46→ * Unpin file from IPFS via backend relay.
47→ */
48→export async function unpinFromIpfs(cid: string): Promise<void> {
49→  await ipfsControllerUnpin({ cid });
50→}
51→
52→/**
53→ * Fetch encrypted file from IPFS via the API proxy.
54→ * Supports progress tracking for larger files via axios onDownloadProgress.
55→ *
56→ * @param cid - IPFS CID of the file
57→ * @param onProgress - Optional callback for download progress
58→ * @returns Encrypted file content as Uint8Array
59→ */
60→export async function fetchFromIpfs(
61→  cid: string,
62→  onProgress?: DownloadProgressCallback
63→): Promise<Uint8Array> {
64→  const blob = await ipfsControllerGet(cid, {
65→    ...(onProgress && {
66→      onDownloadProgress: (event: AxiosProgressEvent) => {
67→        if (event.total) {
68→          onProgress(event.loaded, event.total);
69→        }
70→      },
71→    }),
72→  });
73→
74→  const buffer = await blob.arrayBuffer();
75→  return new Uint8Array(buffer);
76→}
77→

  1→/**
  2→ * @cipherbox/core - Folder Metadata Encryption
  3→ *
  4→ * Encrypts and decrypts folder metadata using AES-256-GCM.
  5→ * Folder metadata is JSON serialized before encryption.
  6→ */
  7→
  8→import {
  9→  encryptAesGcm,
 10→  decryptAesGcm,
 11→  generateIv,
 12→  bytesToHex,
 13→  hexToBytes,
 14→  CryptoError,
 15→  ECIES_MIN_CIPHERTEXT_SIZE,
 16→} from '@cipherbox/crypto';
 17→import type { FolderMetadata, EncryptedFolderMetadata } from './types';
 18→
 19→/**
 20→ * [SECURITY: MEDIUM-08] Chunk-based base64 encoding to avoid call stack issues
 21→ * with large Uint8Arrays (spread operator has argument limits ~65536)
 22→ */
 23→function uint8ArrayToBase64(bytes: Uint8Array): string {
 24→  const CHUNK_SIZE = 32768;
 25→  let result = '';
 26→  for (let i = 0; i < bytes.length; i += CHUNK_SIZE) {
 27→    const chunk = bytes.subarray(i, Math.min(i + CHUNK_SIZE, bytes.length));
 28→    result += String.fromCharCode(...chunk);
 29→  }
 30→  return btoa(result);
 31→}
 32→
 33→/**
 34→ * [SECURITY: MEDIUM-07] Runtime validation for decrypted folder metadata.
 35→ * Accepts only v2 schema. Rejects v1 data.
 36→ * - v2 children: FolderEntry | FilePointer (with fileMetaIpnsName field)
 37→ */
 38→export function validateFolderMetadata(data: unknown): FolderMetadata {
 39→  if (typeof data !== 'object' || data === null) {
 40→    throw new CryptoError('Invalid metadata format: not an object', 'DECRYPTION_FAILED');
 41→  }
 42→
 43→  const obj = data as Record<string, unknown>;
 44→
 45→  // Only v2 is accepted
 46→  if (obj.version !== 'v2') {
 47→    throw new CryptoError(
 48→      'Invalid metadata format: unsupported version (only v2 accepted)',
 49→      'DECRYPTION_FAILED'
 50→    );
 51→  }
 52→
 53→  // Validate children array
 54→  if (!Array.isArray(obj.children)) {
 55→    throw new CryptoError('Invalid metadata format: children must be array', 'DECRYPTION_FAILED');
 56→  }
 57→
 58→  // Basic validation of each child entry
 59→  for (const child of obj.children) {
 60→    if (typeof child !== 'object' || child === null) {
 61→      throw new CryptoError('Invalid metadata format: invalid child entry', 'DECRYPTION_FAILED');
 62→    }
 63→    const entry = child as Record<string, unknown>;
 64→    if (entry.type !== 'file' && entry.type !== 'folder') {
 65→      throw new CryptoError('Invalid metadata format: unknown child type', 'DECRYPTION_FAILED');
 66→    }
 67→    if (typeof entry.id !== 'string' || typeof entry.name !== 'string') {
 68→      throw new CryptoError('Invalid metadata format: missing id or name', 'DECRYPTION_FAILED');
 69→    }
 70→
 71→    // v2 file children must have fileMetaIpnsName (FilePointer)
 72→    if (entry.type === 'file') {
 73→      const hasIpnsName = typeof entry.fileMetaIpnsName === 'string';
 74→      if (!hasIpnsName) {
 75→        throw new CryptoError(
 76→          'Invalid metadata format: file entry must have fileMetaIpnsName',
 77→          'DECRYPTION_FAILED'
 78→        );
 79→      }
 80→      // Optional: ipnsPrivateKeyEncrypted must be a hex string long enough to hold ECIES output
 81→      if (entry.ipnsPrivateKeyEncrypted !== undefined) {
 82→        if (
 83→          typeof entry.ipnsPrivateKeyEncrypted !== 'string' ||
 84→          entry.ipnsPrivateKeyEncrypted.length < ECIES_MIN_CIPHERTEXT_SIZE * 2
 85→        ) {
 86→          throw new CryptoError(
 87→            `Invalid metadata format: ipnsPrivateKeyEncrypted must be a hex string (min ${ECIES_MIN_CIPHERTEXT_SIZE * 2} chars)`,
 88→            'DECRYPTION_FAILED'
 89→          );
 90→        }
 91→      }
 92→    }
 93→  }
 94→
 95→  return data as FolderMetadata;
 96→}
 97→
 98→/**
 99→ * Encrypts folder metadata with AES-256-GCM.
100→ *
101→ * @param metadata - Plaintext folder metadata object (v2)
102→ * @param folderKey - 32-byte AES key for this folder
103→ * @returns Encrypted metadata with IV (hex) and ciphertext (base64)
104→ */
105→export async function encryptFolderMetadata(
106→  metadata: FolderMetadata,
107→  folderKey: Uint8Array
108→): Promise<EncryptedFolderMetadata> {
109→  // Generate random IV for this encryption
110→  const iv = generateIv();
111→
112→  // Serialize metadata to JSON bytes
113→  const plaintext = new TextEncoder().encode(JSON.stringify(metadata));
114→
115→  // Encrypt with AES-256-GCM
116→  const ciphertext = await encryptAesGcm(plaintext, folderKey, iv);
117→
118→  // Encode for storage
119→  // [SECURITY: MEDIUM-08] Use chunked base64 encoding for large metadata
120→  return {
121→    iv: bytesToHex(iv),
122→    data: uint8ArrayToBase64(ciphertext),
123→  };
124→}
125→
126→/**
127→ * Decrypts folder metadata encrypted with AES-256-GCM.
128→ * Returns v2 metadata only. Rejects v1 data.
129→ *
130→ * @param encrypted - Encrypted metadata with IV (hex) and ciphertext (base64)
131→ * @param folderKey - 32-byte AES key for this folder
132→ * @returns Decrypted folder metadata object (v2)
133→ * @throws CryptoError if decryption fails (wrong key, corrupted data, etc.)
134→ */
135→export async function decryptFolderMetadata(
136→  encrypted: EncryptedFolderMetadata,
137→  folderKey: Uint8Array
138→): Promise<FolderMetadata> {
139→  // Decode IV and ciphertext
140→  const iv = hexToBytes(encrypted.iv);
141→  const ciphertext = Uint8Array.from(atob(encrypted.data), (c) => c.charCodeAt(0));
142→
143→  // Decrypt with AES-256-GCM
144→  const plaintext = await decryptAesGcm(ciphertext, folderKey, iv);
145→
146→  // Parse JSON back to metadata object
147→  // [SECURITY: MEDIUM-07] Validate the decrypted data before returning
148→  const parsed = JSON.parse(new TextDecoder().decode(plaintext));
149→  return validateFolderMetadata(parsed);
150→}
151→

 1→/**
 2→ * @cipherbox/core - Folder Metadata Types
 3→ *
 4→ * Type definitions for encrypted folder metadata stored in IPNS records.
 5→ * v2 schema with per-file IPNS pointers (FilePointer children).
 6→ */
 7→
 8→import type { FilePointer } from '../file/types';
 9→
10→/**
11→ * Decrypted folder metadata structure (v2).
12→ * The entire FolderMetadata object is encrypted as a single blob with AES-256-GCM.
13→ * Children are FolderEntry (subfolders) or FilePointer (slim IPNS references).
14→ */
15→export type FolderMetadata = {
16→  /** Schema version */
17→  version: 'v2';
18→  /** Folders and file pointers in this folder */
19→  children: FolderChild[];
20→};
21→
22→/**
23→ * A child entry can be either a folder or a file pointer.
24→ */
