 40→    const raw = this.configService.get<string>('RECYCLE_BIN_RETENTION_DAYS');
 41→    let retentionDays = Number(raw);
 42→    if (!Number.isFinite(retentionDays) || retentionDays < 0) {
 43→      retentionDays = 30;
 44→    }
 45→    return {
 46→      recycleBinRetentionDays: retentionDays,
 47→    };
 48→  }
 49→
 50→  /**
 51→   * Initialize a new vault for a user
 52→   * Creates the vault with encrypted keys on first sign-in
 53→   *
 54→   * @throws ConflictException if vault already exists for user
 55→   */
 56→  async initializeVault(userId: string, dto: InitVaultDto): Promise<VaultResponseDto> {
 57→    // Check if vault already exists
 58→    const existingVault = await this.vaultRepository.findOne({
 59→      where: { ownerId: userId },
 60→    });
 61→
 62→    if (existingVault) {
 63→      throw new ConflictException('Vault already exists for this user');
 64→    }
 65→
 66→    // Decode hex strings to buffers
 67→    const vault = this.vaultRepository.create({
 68→      ownerId: userId,
 69→      ownerPublicKey: Buffer.from(dto.ownerPublicKey, 'hex'),
 70→      rootIpnsName: dto.rootIpnsName,
 71→      initializedAt: null,
 72→    });
 73→
 74→    const savedVault = await this.vaultRepository.save(vault);
 75→
 76→    // Create root folder IPNS entry for publish tracking
 77→    // This allows IPNS publishes to work without requiring TEE fields on every publish
 78→    const rootFolderIpns = this.folderIpnsRepository.create({
 79→      userId,
 80→      ipnsName: dto.rootIpnsName,
 81→      latestCid: null, // No content yet
 82→      sequenceNumber: '0',
 83→      encryptedIpnsPrivateKey: null, // TEE key added when TEE is implemented
 84→      keyEpoch: null,
 85→      isRoot: true,
 86→    });
 87→    await this.folderIpnsRepository.save(rootFolderIpns);
 88→
 89→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
 90→    return this.toVaultResponse(savedVault, teeKeys);
 91→  }
 92→
 93→  /**
 94→   * Get vault for a user
 95→   *
 96→   * @throws NotFoundException if vault does not exist
 97→   */
 98→  async getVault(userId: string): Promise<VaultResponseDto> {
 99→    const vault = await this.vaultRepository.findOne({
100→      where: { ownerId: userId },
101→    });
102→
103→    if (!vault) {
104→      throw new NotFoundException('Vault not found');
105→    }
106→
107→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
108→    return this.toVaultResponse(vault, teeKeys);
109→  }
110→
111→  /**
112→   * Check if vault exists for user (returns null if not)
113→   */
114→  async findVault(userId: string): Promise<VaultResponseDto | null> {
115→    const vault = await this.vaultRepository.findOne({
116→      where: { ownerId: userId },
117→    });
118→
119→    if (!vault) return null;
120→
121→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
122→    return this.toVaultResponse(vault, teeKeys);
123→  }
124→
125→  /**
126→   * Get current storage quota usage for a user
127→   */
128→  async getQuota(userId: string): Promise<QuotaResponseDto> {
129→    const result = await this.pinnedCidRepository
130→      .createQueryBuilder('pin')
131→      .select('COALESCE(SUM(pin.size_bytes), 0)', 'total')
132→      .where('pin.user_id = :userId', { userId })
133→      .getRawOne<{ total: string }>();
134→
135→    const usedBytes = parseInt(result?.total ?? '0', 10);
136→    const remainingBytes = Math.max(0, QUOTA_LIMIT_BYTES - usedBytes);
137→
138→    return {
139→      usedBytes,
140→      limitBytes: QUOTA_LIMIT_BYTES,
141→      remainingBytes,
142→    };
143→  }
144→
145→  /**
146→   * Check if user has sufficient quota for additional storage
147→   *
148→   * @returns true if (current usage + additionalBytes) <= quota limit
149→   */
150→  async checkQuota(userId: string, additionalBytes: number): Promise<boolean> {
151→    const quota = await this.getQuota(userId);
152→    return quota.usedBytes + additionalBytes <= QUOTA_LIMIT_BYTES;
153→  }
154→
155→  /**
156→   * Record a pinned CID for quota tracking
157→   * Uses upsert (ON CONFLICT DO NOTHING) for idempotency
158→   */
159→  async recordPin(userId: string, cid: string, sizeBytes: number): Promise<void> {
160→    await this.pinnedCidRepository
161→      .createQueryBuilder()
162→      .insert()
163→      .into(PinnedCid)
164→      .values({
165→        userId,
166→        cid,
167→        sizeBytes: sizeBytes.toString(),
168→      })
169→      .orIgnore() // ON CONFLICT DO NOTHING for idempotency
170→      .execute();
171→  }
172→
173→  /**
174→   * Remove a pinned CID record
175→   * Idempotent - no error if CID not found
176→   */
177→  async recordUnpin(userId: string, cid: string): Promise<void> {
178→    await this.pinnedCidRepository.delete({
179→      userId,
180→      cid,
181→    });
182→  }
183→
184→  /**
185→   * Mark vault as initialized (first file uploaded)
186→   */
187→  async markInitialized(userId: string): Promise<void> {
188→    await this.vaultRepository.update({ ownerId: userId }, { initializedAt: new Date() });
189→  }
190→
191→  /**
192→   * Get export data for independent recovery.
193→   * Returns the minimal set of fields needed to reconstruct the vault:
194→   * root IPNS name + encrypted root keys + derivation hints.
195→   */
196→  async getExportData(userId: string): Promise<VaultExportDto> {
197→    const vault = await this.vaultRepository.findOne({
198→      where: { ownerId: userId },
199→    });
200→
201→    if (!vault) {
202→      throw new NotFoundException('Vault not found');
203→    }
204→
205→    const user = await this.userRepository.findOne({
206→      where: { id: userId },
207→    });
208→
209→    return {
210→      format: 'cipherbox-vault-export',
211→      version: '1.0',
212→      exportedAt: new Date().toISOString(),
213→      rootIpnsName: vault.rootIpnsName,
214→      derivationMethod: user ? 'web3auth' : null,
215→    };
216→  }
217→
218→  /**
219→   * Convert Vault entity to response DTO with hex-encoded fields
220→   */
221→  private toVaultResponse(vault: Vault, teeKeys: TeeKeysDto | null = null): VaultResponseDto {
222→    return {
223→      id: vault.id,
224→      ownerPublicKey: vault.ownerPublicKey.toString('hex'),
225→      rootIpnsName: vault.rootIpnsName,
226→      createdAt: vault.createdAt,
227→      initializedAt: vault.initializedAt,
228→      teeKeys,
229→    };
230→  }
231→}
