+//! Vault blob v2 format: binary envelope for root folder IPFS blobs.
+//!
+//! Format: 0x02 | uint16_BE(key_len) | ECIES_encrypted_key | AES_GCM_metadata_json
+//!
+//! v1 blobs are plain JSON: {"iv":"...","data":"..."}
+//! v2 blobs prepend the ECIES-wrapped rootFolderKey before the metadata JSON.
+
+/// Version byte for v2 format.
+pub const BLOB_V2_VERSION: u8 = 0x02;
+
+/// Detect whether a vault blob is v1 (JSON) or v2 (binary envelope).
+///
+/// v1 blobs start with 0x7B ('{' -- JSON). v2 blobs start with 0x02.
+pub fn detect_blob_version(blob: &[u8]) -> u8 {
+    if !blob.is_empty() && blob[0] == BLOB_V2_VERSION {
+        2
+    } else {
+        1
+    }
+}
+
+/// Serialize a vault blob v2.
+///
+/// Produces: `0x02 | uint16_BE(key_len) | encrypted_root_folder_key | encrypted_metadata_json`
+pub fn serialize_vault_blob_v2(
+    encrypted_root_folder_key: &[u8],
+    encrypted_metadata_json: &[u8],
+) -> Result<Vec<u8>, String> {
+    if encrypted_root_folder_key.len() > u16::MAX as usize {
+        return Err(format!(
+            "Encrypted key too long for v2 blob ({} bytes, max {})",
+            encrypted_root_folder_key.len(),
+            u16::MAX
+        ));
+    }
+    let key_len = encrypted_root_folder_key.len() as u16;
+    let mut result =
+        Vec::with_capacity(3 + encrypted_root_folder_key.len() + encrypted_metadata_json.len());
+    result.push(BLOB_V2_VERSION);
+    result.push((key_len >> 8) as u8);
+    result.push((key_len & 0xff) as u8);
+    result.extend_from_slice(encrypted_root_folder_key);
+    result.extend_from_slice(encrypted_metadata_json);
+    Ok(result)
+}
+
+/// Deserialize a vault blob v2 into (encrypted_key, encrypted_metadata_json).
+///
+/// Returns borrowed slices into the original blob for zero-copy parsing.
+pub fn deserialize_vault_blob_v2(blob: &[u8]) -> Result<(&[u8], &[u8]), String> {
+    if blob.len() < 3 {
+        return Err(format!(
+            "Vault blob too short for v2 header (need at least 3 bytes, have {})",
+            blob.len()
+        ));
+    }
+    if blob[0] != BLOB_V2_VERSION {
+        return Err("Not a v2 vault blob".into());
+    }
+    let key_len = ((blob[1] as usize) << 8) | (blob[2] as usize);
+    if blob.len() < 3 + key_len {
+        return Err(format!(
+            "Vault blob too short for key (expected {} bytes, have {})",
+            key_len,
+            blob.len() - 3
+        ));
+    }
+    Ok((&blob[3..3 + key_len], &blob[3 + key_len..]))
+}","path":"apps/desktop/src-tauri/src/crypto/vault_blob.rs","commit_id":"e7a371fbca114238e1ce2d8c7c6bfa7a311bda0e","original_commit_id":"1c11ff4832ffc606fd989e2ce4a09a6df2f7f2a4","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Fixed in e7a371f — added zero-length rejection in both `serialize_vault_blob_v2` and `deserialize_vault_blob_v2` in Rust. Updated `test_zero_length_key` → `test_zero_length_key_rejected` to assert errors from both functions. TypeScript and Rust are now consistent: key_len=0 is invalid in both directions on both platforms.","created_at":"2026-03-24T03:50:42Z","updated_at":"2026-03-24T03:50:42Z","html_url":"https://github.com/FSM1/cipher-box/pull/344#discussion_r2978828590","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/344","_links":{"self":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2978828590"},"html":{"href":"https://github.com/FSM1/cipher-box/pull/344#discussion_r2978828590"},"pull_request":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/344"}},"reactions":{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2978828590/reactions