try {
  // Try to fetch existing vault
  const existingVault = await vaultApi.getVault();

  // Store TEE keys if available
  if (existingVault.teeKeys) {
    useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
  }

  // All users read rootFolderKey from IPFS v2 blob (no DB fallback)
  const ipnsKeypair = await deriveVaultIpnsKeypair(userKeypair.privateKey);
  const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);

  const resolved = await resolveIpnsRecord(ipnsName);
  if (!resolved) throw new Error('IPNS name not found for vault');

  const blobBytes = await fetchFromIpfs(resolved.cid);

  if (detectBlobVersion(blobBytes) !== 2) {
    throw new Error('Vault blob is not v2 format');
  }

  const { encryptedRootFolderKey: encKey } = deserializeVaultBlobV2(blobBytes);
  const rootFolderKey = await unwrapKey(encKey, userKeypair.privateKey);

  setVaultKeys({
    rootFolderKey,
    rootIpnsKeypair: ipnsKeypair,
    rootIpnsName: existingVault.rootIpnsName,
    vaultId: existingVault.id,
  });
} catch (error) {
  const is404 = (error as { response?: { status?: number } })?.response?.status === 404;

  if (is404) {
    // New user -- initialize vault with IPFS-native v2 blob
    console.log('[Auth] New user -- initializing vault with v2 blob');
    const newVault = await initializeVault(userKeypair.privateKey);
    const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);

    // 1. ECIES-wrap rootFolderKey for v2 blob header
    const encryptedRootFolderKey = await wrapKey(newVault.rootFolderKey, userKeypair.publicKey);

    // 2. Create empty folder metadata, encrypt with rootFolderKey
    const emptyMetadata: FolderMetadata = { version: 'v2', children: [] };
    const encrypted = await encryptFolderMetadata(emptyMetadata, newVault.rootFolderKey);
    const metadataJsonBytes = new TextEncoder().encode(JSON.stringify(encrypted));

    // 3. Serialize as v2 blob (ECIES-wrapped key + AES-GCM metadata)
    const v2Blob = serializeVaultBlobV2(encryptedRootFolderKey, metadataJsonBytes);

    // 4. Upload v2 blob to IPFS
    const uploadResult = await addToIpfs(new Blob([v2Blob as BlobPart]));

    // 5. Create and publish IPNS record (sequence 0)
    const publishResult = await createAndPublishIpnsRecord({
      ipnsPrivateKey: newVault.rootIpnsKeypair.privateKey,
      ipnsName: rootIpnsName,
      metadataCid: uploadResult.cid,
      sequenceNumber: 0n,
      expectedSequenceNumber: undefined,
    });

    if (!publishResult.success) {
      throw new Error('Failed to publish initial IPNS record for new vault');
    }

    // 6. Register vault with API (no crypto fields -- IPFS-only)
    const storedVault = await vaultApi.initVault({
      ownerPublicKey: bytesToHex(userKeypair.publicKey),
      rootIpnsName,
    });

    if (storedVault.teeKeys) {
      useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
    }

    setVaultKeys({
      rootFolderKey: newVault.rootFolderKey,
      rootIpnsKeypair: newVault.rootIpnsKeypair,
      rootIpnsName,
      vaultId: storedVault.id,
      isNewVault: true,
    });
  } else {
    console.error('[useAuth] Failed to load vault:', error);
    throw error;
  }
}

// Initialize SDK client with decrypted vault keys
const vaultState = useVaultStore.getState();
const authState = useAuthStore.getState();
if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
  const apiUrl = import.meta.env.VITE_API_URL || window.location.origin + '/api';
  const getAccessToken = async () => {
    const state = useAuthStore.getState();
    return state.accessToken || '';
  };

//! HKDF-SHA256 deterministic IPNS keypair derivation.
//!
//! Derives deterministic Ed25519 IPNS keypairs from a secp256k1 private key
//! using HKDF-SHA256 with domain-separated info strings. Matches the TypeScript
//! implementations in `@cipherbox/crypto` (vault/derive-ipns.ts, file/derive-ipns.ts,
//! registry/derive-ipns.ts).
//!
//! Derivation path:
//!   secp256k1 privateKey (32 bytes)
//!     -> HKDF-SHA256(salt="CipherBox-v1", info=<domain-specific>)
//!     -> 32-byte Ed25519 seed
//!     -> Ed25519 keypair
//!     -> IPNS name (k51...)

use ed25519_dalek::SigningKey;
use hkdf::Hkdf;
use sha2::Sha256;
use thiserror::Error;
use zeroize::{Zeroize, Zeroizing};

use super::ipns;

/// Common HKDF salt for all CipherBox derivations.
const HKDF_SALT: &[u8] = b"CipherBox-v1";

/// HKDF info for vault IPNS keypair derivation.
const VAULT_HKDF_INFO: &[u8] = b"cipherbox-vault-ipns-v1";

/// HKDF info for device registry IPNS keypair derivation.
const REGISTRY_HKDF_INFO: &[u8] = b"cipherbox-device-registry-ipns-v1";

/// HKDF info for recycle bin IPNS keypair derivation.
const BIN_HKDF_INFO: &[u8] = b"cipherbox-recycle-bin-ipns-v1";

/// HKDF info prefix for per-file IPNS keypair derivation.
const FILE_HKDF_INFO_PREFIX: &str = "cipherbox-file-ipns-v1:";

/// Minimum file ID length (matches TypeScript validation).
const MIN_FILE_ID_LENGTH: usize = 10;

#[derive(Debug, Error)]
pub enum HkdfError {
    #[error("Invalid key size")]
    InvalidKeySize,
    #[error("HKDF derivation failed")]
    DerivationFailed,
    #[error("IPNS name derivation failed")]
    IpnsDerivationFailed,
    #[error("Invalid file ID: must be at least {MIN_FILE_ID_LENGTH} characters")]
    InvalidFileId,
}

/// Internal helper: derive an Ed25519 keypair and IPNS name from HKDF output.
///
/// All three public functions follow the same pattern and delegate here.
fn derive_ipns_keypair(
    user_private_key: &[u8; 32],
    info: &[u8],
) -> Result<(Zeroizing<Vec<u8>>, Vec<u8>, String), HkdfError> {
    // 1. HKDF-SHA256: extract + expand
    let hk = Hkdf::<Sha256>::new(Some(HKDF_SALT), user_private_key);
    let mut okm = [0u8; 32];
    hk.expand(info, &mut okm)
        .map_err(|_| HkdfError::DerivationFailed)?;

    // 2. Ed25519 keypair from 32-byte seed
    let signing_key = SigningKey::from_bytes(&okm);
    okm.zeroize();
    let verifying_key = signing_key.verifying_key();

    let private_key = Zeroizing::new(signing_key.to_bytes().to_vec());
    let public_key = verifying_key.to_bytes().to_vec();

    // 3. Derive IPNS name from public key
    let pk_array: [u8; 32] = verifying_key.to_bytes();
    let ipns_name = ipns::derive_ipns_name(&pk_array).map_err(|_| HkdfError::IpnsDerivationFailed)?;

    Ok((private_key, public_key, ipns_name))
}

/// Derive the deterministic Ed25519 IPNS keypair for the user's vault.
///
/// Uses HKDF info "cipherbox-vault-ipns-v1" for domain separation.
///
/// Given the same secp256k1 privateKey, this always produces the same
/// IPNS name, enabling vault discovery from any device with the user's key.
///
/// Returns (ed25519_private_key, ed25519_public_key, ipns_name).
pub fn derive_vault_ipns_keypair(
    user_private_key: &[u8; 32],
) -> Result<(Zeroizing<Vec<u8>>, Vec<u8>, String), HkdfError> {
    derive_ipns_keypair(user_private_key, VAULT_HKDF_INFO)
}

/// Derive a deterministic Ed25519 IPNS keypair for a specific file.
///
/// Uses HKDF info "cipherbox-file-ipns-v1:{fileId}" for per-file domain separation.
///
/// Returns (ed25519_private_key, ed25519_public_key, ipns_name).
pub fn derive_file_ipns_keypair(
    user_private_key: &[u8; 32],
    file_id: &str,
) -> Result<(Zeroizing<Vec<u8>>, Vec<u8>, String), HkdfError> {
    if file_id.len() < MIN_FILE_ID_LENGTH {
        return Err(HkdfError::InvalidFileId);
    }

    let info = format!("{}{}", FILE_HKDF_INFO_PREFIX, file_id);
    derive_ipns_keypair(user_private_key, info.as_bytes())
}

/// Derive the deterministic Ed25519 IPNS keypair for the device registry.
///
/// Uses HKDF info "cipherbox-device-registry-ipns-v1" for domain separation.
///
/// Returns (ed25519_private_key, ed25519_public_key, ipns_name).
pub fn derive_registry_ipns_keypair(
    user_private_key: &[u8; 32],
) -> Result<(Zeroizing<Vec<u8>>, Vec<u8>, String), HkdfError> {
    derive_ipns_keypair(user_private_key, REGISTRY_HKDF_INFO)
}

/// Derive the deterministic Ed25519 IPNS keypair for the recycle bin.
///
/// Uses HKDF info "cipherbox-recycle-bin-ipns-v1" for domain separation.
///
/// Returns (ed25519_private_key, ed25519_public_key, ipns_name).
pub fn derive_bin_ipns_keypair(
    user_private_key: &[u8; 32],
) -> Result<(Zeroizing<Vec<u8>>, Vec<u8>, String), HkdfError> {
    derive_ipns_keypair(user_private_key, BIN_HKDF_INFO)
}

