  2→ * @cipherbox/core - Vault Blob v2 Tests
  3→ *
  4→ * Unit tests for v2 binary blob serialize/deserialize/detect functions.
  5→ */
  6→
  7→import { describe, it, expect } from 'vitest';
  8→import {
  9→  serializeVaultBlobV2,
 10→  deserializeVaultBlobV2,
 11→  detectBlobVersion,
 12→  BLOB_V2_VERSION,
 13→} from '../vault/blob';
 14→
 15→describe('Vault Blob v2', () => {
 16→  describe('BLOB_V2_VERSION', () => {
 17→    it('should equal 0x02', () => {
 18→      expect(BLOB_V2_VERSION).toBe(0x02);
 19→    });
 20→  });
 21→
 22→  describe('serializeVaultBlobV2', () => {
 23→    it('should produce correct binary format with 129-byte key', () => {
 24→      // Simulate a 129-byte ECIES-encrypted rootFolderKey
 25→      const encryptedKey = new Uint8Array(129);
 26→      encryptedKey.fill(0xaa);
 27→
 28→      const metadataJson = new TextEncoder().encode('{"iv":"abc","data":"def"}');
 29→
 30→      const blob = serializeVaultBlobV2(encryptedKey, metadataJson);
 31→
 32→      // Total: 1 (version) + 2 (key_len) + 129 (key) + 24 (metadata)
 33→      expect(blob.length).toBe(1 + 2 + 129 + metadataJson.length);
 34→
 35→      // Version byte
 36→      expect(blob[0]).toBe(0x02);
 37→
 38→      // Big-endian uint16 key length: 129 = 0x0081
 39→      expect(blob[1]).toBe(0x00);
 40→      expect(blob[2]).toBe(0x81);
 41→
 42→      // Key bytes
 43→      expect(blob.slice(3, 3 + 129)).toEqual(encryptedKey);
 44→
 45→      // Metadata bytes
 46→      expect(blob.slice(3 + 129)).toEqual(metadataJson);
 47→    });
 48→
 49→    it('should handle variable key lengths', () => {
 50→      // Minimum ECIES ciphertext might be 81 bytes (33 compressed PK + 16 nonce + 16 tag + 16 ciphertext)
 51→      const encryptedKey = new Uint8Array(81);
 52→      encryptedKey.fill(0xbb);
 53→
 54→      const metadataJson = new Uint8Array([0x01, 0x02, 0x03]);
 55→
 56→      const blob = serializeVaultBlobV2(encryptedKey, metadataJson);
 57→
 58→      // Total: 1 + 2 + 81 + 3 = 87
